fn audit_log_path(root: &Path, tenant_id: &str) -> PathBuf {
    root.join("tenants")
        .join(tenant_storage_key(tenant_id))
        .join("audit")
        .join("events.jsonl")
}

fn corrupt_submission_record_tenant(
    root: &Path,
    stored_tenant_id: &str,
    forged_tenant_id: &str,
    submission_id: Uuid,
) {
    let path = submission_metadata_path(root, stored_tenant_id, submission_id);
    let body = std::fs::read_to_string(&path).expect("metadata reads for corruption");
    let mut value: serde_json::Value = serde_json::from_str(&body).expect("metadata json parses");
    value["tenant_id"] = serde_json::json!(forged_tenant_id);
    value["tenant_storage_ref"] = serde_json::json!(tenant_storage_ref(forged_tenant_id));
    value["submitted_tenant_scope_ref"] = serde_json::json!(tenant_storage_ref(forged_tenant_id));
    std::fs::write(
        &path,
        serde_json::to_string_pretty(&value).expect("metadata serializes"),
    )
    .expect("metadata corruption writes");
}

fn read_raw_audit_events(
    root: &Path,
    tenant_id: &str,
) -> anyhow::Result<Vec<TraceCommonsAuditEvent>> {
    let path = audit_log_path(root, tenant_id);
    let body = std::fs::read_to_string(&path)
        .with_context(|| format!("failed to read raw audit events {}", path.display()))?;
    body.lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(|line| serde_json::from_str(line).context("failed to parse raw audit event"))
        .collect()
}

#[tokio::test]
async fn trace_content_read_per_source_emits_one_row_per_object_ref() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let auth = test_reviewer_auth("tenant-a");
    let submission_id = Uuid::new_v4();
    let object_refs = [Uuid::new_v4(), Uuid::new_v4(), Uuid::new_v4()];

    append_trace_content_read_audit_per_source(
        state.as_ref(),
        &auth,
        submission_id,
        &object_refs,
        "replay_export",
        Some("per-source coverage"),
    )
    .await
    .expect("per-source variant writes rows");

    let events = read_raw_audit_events(temp.path(), "tenant-a").expect("audit events parse");
    assert_eq!(events.len(), object_refs.len());
    for event in &events {
        assert_eq!(event.submission_id, submission_id);
        assert_eq!(event.kind, "trace_content_read");
        assert!(event.event_hash.is_some());
        assert!(event.previous_event_hash.is_some());
    }
    // Each row must have a distinct event_hash and link to the prior row's hash.
    let mut prev = "sha256:genesis".to_string();
    for event in &events {
        assert_eq!(event.previous_event_hash.as_deref(), Some(prev.as_str()));
        prev = event.event_hash.clone().unwrap();
    }
}

