#[test]
fn remote_object_delete_request_hashes_sensitive_refs_for_adapter_boundary() {
    let submission_id =
        Uuid::parse_str("171746f9-4d3d-4b44-84f4-61866da7a3f6").expect("uuid parses");
    let object_ref_id =
        Uuid::parse_str("21d84c1a-3b25-47e1-bb93-eae6f1ef128a").expect("uuid parses");
    let propagation_item_id =
        Uuid::parse_str("7fc7da51-5871-466a-a4a9-0ebd34d76baf").expect("uuid parses");
    let now = Utc::now();
    let tenant = TenantAuth {
        tenant_id: "tenant-a".to_string(),
        role: TokenRole::RevocationWorker,
        principal_ref: principal_storage_ref("revocation-worker-token-a"),
        expires_at: None,
        auth_method: TraceAuthMethod::StaticToken,
        signed_claim_issuer: None,
        signed_claim_audiences: BTreeSet::new(),
        signed_claim_subject: None,
        allowed_consent_scopes: BTreeSet::new(),
        allowed_uses: BTreeSet::new(),
    };
    let item = StorageTraceRevocationPropagationItemRecord {
        tenant_id: "tenant-a".to_string(),
        propagation_item_id,
        source_submission_id: submission_id,
        trace_id: Uuid::new_v4(),
        target_kind: StorageTraceRevocationPropagationTargetKind::ObjectRef,
        target: StorageTraceRevocationPropagationTarget::ObjectRef { object_ref_id },
        action: StorageTraceRevocationPropagationAction::DeleteObjectPayload,
        status: StorageTraceRevocationPropagationItemStatus::Pending,
        idempotency_key: sha256_prefixed("remote-object-delete-request-test"),
        reason: "revoked trace remote object payload deletion".to_string(),
        attempt_count: 0,
        last_error: None,
        next_attempt_at: None,
        completed_at: None,
        evidence_hash: None,
        metadata: BTreeMap::new(),
        created_at: now,
        updated_at: now,
    };
    let object_ref = StorageTraceObjectRefRecord {
        tenant_id: "tenant-a".to_string(),
        submission_id,
        object_ref_id,
        artifact_kind: StorageTraceObjectArtifactKind::SubmittedEnvelope,
        object_store: TRACE_COMMONS_SERVICE_REMOTE_DISABLED_OBJECT_STORE.to_string(),
        object_key: "tenants/tenant-secret/object-key-secret.json".to_string(),
        content_sha256: "sha256:cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc"
            .to_string(),
        encryption_key_ref: "kms-secret-ref".to_string(),
        size_bytes: 128,
        compression: None,
        created_by_job_id: None,
        invalidated_at: None,
        deleted_at: None,
        updated_at: now,
        created_at: now,
    };

    let request = remote_object_delete_request_for_revocation(&tenant, &item, &object_ref);
    assert_eq!(request.tenant_storage_ref, tenant_storage_ref("tenant-a"));
    assert_eq!(request.propagation_item_id, propagation_item_id);
    assert_eq!(request.object_ref_id, object_ref_id);
    assert_eq!(request.object_key, object_ref.object_key);
    assert_eq!(
        request.object_key_hash,
        sha256_prefixed("tenants/tenant-secret/object-key-secret.json")
    );
    assert_eq!(
        request.encryption_key_ref_hash,
        sha256_prefixed("kms-secret-ref")
    );
    assert!(request.source_submission_ref_hash.starts_with("sha256:"));
    let request_text = serde_json::to_string(&request).expect("request serializes");
    assert!(!request_text.contains("tenant-a"));
    assert!(!request_text.contains(&submission_id.to_string()));
    assert!(!request_text.contains("kms-secret-ref"));
}

#[test]
fn remote_service_file_adapter_enables_object_io_without_plaintext_fallback() {
    let temp = tempfile::tempdir().expect("temp dir");
    let key = trace_commons_server::secrets::keychain::generate_master_key_hex();
    let config = TraceRemoteObjectStoreConfig::from_parts(
        Some("file_system"),
        Some(temp.path().to_str().expect("utf8 temp path")),
        Some("kms-key-ref"),
        Some("credential-ref"),
    )
    .expect("file remote config parses");
    let store = ConfiguredTraceArtifactStore::remote_service(config, SecretString::from(key))
        .expect("remote service store builds");
    let payload = serde_json::json!({"safe": true, "body": "<redacted>"});

    assert_eq!(
        store.object_store_name(),
        TRACE_COMMONS_SERVICE_REMOTE_OBJECT_STORE
    );
    assert!(store.object_io_enabled());
    assert!(store.object_primary_eligible());
    assert!(!store.plaintext_compatibility_allowed());

    let receipt = store
        .put_json(
            "tenant_sha256:remote",
            TraceArtifactKind::ContributionEnvelope,
            "remote-submit",
            &payload,
        )
        .expect("remote service artifact writes");
    assert!(
        receipt.object_key.starts_with("v1/tenants/"),
        "remote service receipts use partitioned object keys"
    );
    let read_back: serde_json::Value = store
        .get_json("tenant_sha256:remote", &receipt)
        .expect("remote service artifact reads");
    assert_eq!(read_back, payload);
    assert!(
        store
            .delete_artifact("tenant_sha256:remote", &receipt)
            .expect("remote service artifact deletes")
    );
}

#[test]
fn required_object_store_versioning_guard_rejects_current_adapters() {
    validate_required_object_store_versioning_config(false, None)
        .expect("versioning is optional by default");

    let missing = validate_required_object_store_versioning_config(true, None)
        .expect_err("required versioning needs an object store");
    assert!(
        missing
            .to_string()
            .contains("TRACE_COMMONS_OBJECT_STORE_REQUIRE_VERSIONING")
    );

    let temp = tempfile::tempdir().expect("temp dir");
    let local_store = ConfiguredTraceArtifactStore::new(
        TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE,
        test_artifact_store(temp.path()),
    );
    let local_error = validate_required_object_store_versioning_config(true, Some(&local_store))
        .expect_err("local service store does not provide object versioning");
    assert!(local_error.to_string().contains("object_versioning=false"));

    let remote_temp = tempfile::tempdir().expect("remote artifact temp dir");
    let key = trace_commons_server::secrets::keychain::generate_master_key_hex();
    let remote_config = TraceRemoteObjectStoreConfig::from_parts(
        Some("file_system"),
        Some(remote_temp.path().to_str().expect("utf8 temp path")),
        Some("kms-key-ref"),
        Some("credential-ref"),
    )
    .expect("file remote config parses");
    let remote_store =
        ConfiguredTraceArtifactStore::remote_service(remote_config, SecretString::from(key))
            .expect("remote service store builds");
    let remote_error = validate_required_object_store_versioning_config(true, Some(&remote_store))
        .expect_err("filesystem remote service store does not provide restore semantics");
    assert!(
        remote_error
            .to_string()
            .contains("restore_after_delete=false")
    );
}

#[test]
fn tenant_rollout_gates_enable_global_or_allowlisted_tenants() {
    let gates = TraceTenantRolloutGates::for_feature(
        TraceTenantRolloutFeature::DbContributorReads,
        &["tenant-a"],
    );
    assert!(gates.enabled_for(
        TraceTenantRolloutFeature::DbContributorReads,
        false,
        "tenant-a"
    ));
    assert!(!gates.enabled_for(
        TraceTenantRolloutFeature::DbContributorReads,
        false,
        "tenant-b"
    ));
    assert!(gates.enabled_for(
        TraceTenantRolloutFeature::DbContributorReads,
        true,
        "tenant-b"
    ));
    assert_eq!(gates.status_counts().get("db_contributor_reads"), Some(&1));
}

#[test]
fn tenant_rollout_gate_dependency_requires_matching_tenant_scope() {
    let gates = TraceTenantRolloutGates::for_feature(
        TraceTenantRolloutFeature::ObjectPrimarySubmitReview,
        &["tenant-a"],
    )
    .with_feature(
        TraceTenantRolloutFeature::DbReviewerReads,
        &["tenant-a", "tenant-b"],
    );
    validate_rollout_gate_dependency(
        &gates,
        TraceTenantRolloutFeature::ObjectPrimarySubmitReview,
        false,
        TraceTenantRolloutFeature::DbReviewerReads,
        false,
        "missing dependency",
    )
    .expect("allowlisted dependency covers feature tenant");

    let missing = validate_rollout_gate_dependency(
        &gates,
        TraceTenantRolloutFeature::ObjectPrimarySubmitReview,
        false,
        TraceTenantRolloutFeature::DbReviewerRequireObjectRefs,
        false,
        "missing dependency",
    )
    .expect_err("missing tenant-scoped dependency is rejected");
    assert!(missing.to_string().contains("missing dependency"));
}

#[test]
fn db_read_cutover_guard_requires_fail_closed_writes_when_reconciliation_is_required() {
    let gates = TraceTenantRolloutGates::for_feature(
        TraceTenantRolloutFeature::DbReviewerReads,
        &["tenant-a"],
    );

    let missing_global = validate_db_read_cutover_guard_config(
        &TraceTenantRolloutGates::default(),
        DbReadCutoverGuardConfig {
            require_db_reconciliation_clean: true,
            db_contributor_reads: true,
            ..DbReadCutoverGuardConfig::default()
        },
    )
    .expect_err("global DB reader promotion needs fail-closed mirror writes");
    assert!(
        missing_global
            .to_string()
            .contains("TRACE_COMMONS_REQUIRE_DB_MIRROR_WRITES")
    );

    let missing_allowlist = validate_db_read_cutover_guard_config(
        &gates,
        DbReadCutoverGuardConfig {
            require_db_reconciliation_clean: true,
            db_reviewer_reads: true,
            ..DbReadCutoverGuardConfig::default()
        },
    )
    .expect_err("tenant-allowlisted DB reader promotion needs fail-closed mirror writes");
    assert!(
        missing_allowlist
            .to_string()
            .contains("TRACE_COMMONS_REQUIRE_DB_MIRROR_WRITES")
    );

    validate_db_read_cutover_guard_config(
        &gates,
        DbReadCutoverGuardConfig {
            require_db_reconciliation_clean: true,
            require_db_mirror_writes: true,
            db_reviewer_reads: true,
            ..DbReadCutoverGuardConfig::default()
        },
    )
    .expect("fail-closed mirror writes allow DB reader promotion");

    validate_db_read_cutover_guard_config(
        &gates,
        DbReadCutoverGuardConfig {
            db_reviewer_reads: true,
            ..DbReadCutoverGuardConfig::default()
        },
    )
    .expect("non-production reconciliation mode does not force fail-closed writes");
}

#[test]
fn object_primary_submit_review_validates_production_guards() {
    validate_object_primary_submit_review_config(
        true,
        true,
        true,
        true,
        true,
        Some(TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE),
    )
    .expect("complete production guard config is valid");

    let cases = [
        (
            false,
            true,
            true,
            true,
            Some(TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE),
            "TRACE_COMMONS_DB_DUAL_WRITE",
        ),
        (
            true,
            false,
            true,
            true,
            Some(TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE),
            "TRACE_COMMONS_REQUIRE_DB_MIRROR_WRITES",
        ),
        (
            true,
            true,
            false,
            true,
            Some(TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE),
            "TRACE_COMMONS_DB_REVIEWER_READS",
        ),
        (
            true,
            true,
            true,
            false,
            Some(TRACE_COMMONS_SERVICE_LOCAL_ENCRYPTED_OBJECT_STORE),
            "TRACE_COMMONS_DB_REVIEWER_REQUIRE_OBJECT_REFS",
        ),
        (true, true, true, true, None, "TRACE_COMMONS_OBJECT_STORE"),
        (
            true,
            true,
            true,
            true,
            Some(TRACE_COMMONS_LEGACY_ENCRYPTED_OBJECT_STORE),
            "TRACE_COMMONS_OBJECT_STORE",
        ),
    ];
    for (
        db_mirror_configured,
        require_db_mirror_writes,
        db_reviewer_reads,
        db_reviewer_require_object_refs,
        artifact_store_name,
        expected,
    ) in cases
    {
        let error = validate_object_primary_submit_review_config(
            true,
            db_mirror_configured,
            require_db_mirror_writes,
            db_reviewer_reads,
            db_reviewer_require_object_refs,
            artifact_store_name,
        )
        .expect_err("incomplete object-primary config must fail");
        assert!(
            error.to_string().contains(expected),
            "expected {expected} in {error}"
        );
    }
}

