#[tokio::test]
async fn signed_claim_reviewer_cannot_review_decision_outside_source_scope_before_body_read() {
    let temp = tempfile::tempdir().expect("temp dir");
    let secret = "review-privileged-abac-secret";
    let state =
        test_state_with_signed_token_verifier(temp.path().to_path_buf(), secret, None, None);
    let exp = (Utc::now() + Duration::minutes(5)).timestamp();
    let contributor_token = signed_tenant_token(
        secret,
        serde_json::json!({
            "tenant_id": "tenant-a",
            "role": "contributor",
            "sub": "benchmark-source-contributor",
            "allowed_consent_scopes": ["benchmark_only"],
            "allowed_uses": ["benchmark_generation"],
            "exp": exp
        }),
    );
    let mut envelope = sample_envelope().await;
    envelope.consent.scopes = vec![ConsentScope::BenchmarkOnly];
    envelope.trace_card.consent_scope = ConsentScope::BenchmarkOnly;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::BenchmarkGeneration];
    let submission_id = envelope.submission_id;

    let Json(receipt) = submit_trace_handler(
        State(state.clone()),
        auth_headers(&contributor_token),
        Json(envelope),
    )
    .await
    .expect("benchmark-scoped quarantined submission succeeds");
    assert_eq!(receipt.status, "quarantined");
    let record = read_submission_record(temp.path(), "tenant-a", submission_id)
        .expect("submission record reads")
        .expect("submission record exists");
    delete_trace_objects_for_record(state.as_ref(), &record)
        .expect("test removes body payload to prove ABAC runs before body read");

    let reviewer_token = signed_tenant_token(
        secret,
        serde_json::json!({
            "tenant_id": "tenant-a",
            "role": "reviewer",
            "sub": "evaluation-only-reviewer",
            "allowed_consent_scopes": ["debugging_evaluation"],
            "allowed_uses": ["evaluation"],
            "exp": exp
        }),
    );
    let error = review_decision_handler(
        State(state),
        auth_headers(&reviewer_token),
        AxumPath(submission_id),
        Json(TraceReviewDecisionRequest {
            decision: TraceReviewDecision::Approve,
            reason: Some("reviewer claim is intentionally out of scope".to_string()),
            credit_points_pending: None,
        }),
    )
    .await
    .expect_err("scoped reviewer cannot review source outside claim scope");
    assert_eq!(error.0, StatusCode::FORBIDDEN);
}

#[tokio::test]
async fn tenant_policy_blocks_maintenance_purge_for_disallowed_source_before_deletion() {
    let temp = tempfile::tempdir().expect("temp dir");
    let mut state = test_state(temp.path().to_path_buf());
    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::BenchmarkOnly];
    envelope.trace_card.consent_scope = ConsentScope::BenchmarkOnly;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::BenchmarkGeneration];
    let submission_id = envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        Json(envelope),
    )
    .await
    .expect("benchmark-only source submission succeeds");
    let mut record = read_submission_record(temp.path(), "tenant-a", submission_id)
        .expect("submission record reads")
        .expect("submission record exists");
    record.status = TraceCorpusStatus::Expired;
    record.expires_at = Some(Utc::now() - Duration::hours(1));
    write_submission_record(temp.path(), &record).expect("expired record writes");

    let mut policies = BTreeMap::new();
    policies.insert(
        "tenant-a".to_string(),
        TenantSubmissionPolicy {
            allowed_consent_scopes: BTreeSet::from([ConsentScope::DebuggingEvaluation]),
            allowed_uses: BTreeSet::from([TraceAllowedUse::Evaluation]),
        },
    );
    Arc::make_mut(&mut state).tenant_policies = Arc::new(policies);

    let error = maintenance_handler(
        State(state),
        auth_headers("admin-token-a"),
        Json(TraceMaintenanceRequest {
            purpose: Some("policy_disallowed_purge".to_string()),
            dry_run: false,
            backfill_db_mirror: false,
            index_vectors: false,
            reconcile_db_mirror: false,
            verify_audit_chain: false,
            prune_export_cache: false,
            max_export_age_hours: None,
            purge_expired_before: Some(Utc::now()),
        }),
    )
    .await
    .expect_err("tenant policy blocks purge before deletion");
    assert_eq!(error.0, StatusCode::FORBIDDEN);

    let record = read_submission_record(temp.path(), "tenant-a", submission_id)
        .expect("submission record reads after denied purge")
        .expect("submission record still exists");
    assert_eq!(record.status, TraceCorpusStatus::Expired);
    assert!(record.purged_at.is_none());
}

#[tokio::test]
async fn tenant_policy_blocks_privileged_revocation_but_not_owner_revocation() {
    let temp = tempfile::tempdir().expect("temp dir");
    let mut state = test_state(temp.path().to_path_buf());
    let mut envelope = sample_envelope().await;
    envelope.consent.scopes = vec![ConsentScope::BenchmarkOnly];
    envelope.trace_card.consent_scope = ConsentScope::BenchmarkOnly;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::BenchmarkGeneration];
    let submission_id = envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        Json(envelope),
    )
    .await
    .expect("benchmark-only source submission succeeds");
    let mut record = read_submission_record(temp.path(), "tenant-a", submission_id)
        .expect("submission record reads")
        .expect("submission record exists");
    record.auth_principal_ref = legacy_principal_ref();
    write_submission_record(temp.path(), &record)
        .expect("legacy-principal submission record writes");

    let mut policies = BTreeMap::new();
    policies.insert(
        "tenant-a".to_string(),
        TenantSubmissionPolicy {
            allowed_consent_scopes: BTreeSet::from([ConsentScope::DebuggingEvaluation]),
            allowed_uses: BTreeSet::from([TraceAllowedUse::Evaluation]),
        },
    );
    Arc::make_mut(&mut state).tenant_policies = Arc::new(policies);

    let reviewer_error = revoke_trace_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        AxumPath(submission_id),
    )
    .await
    .expect_err("tenant policy blocks privileged tombstone write");
    assert_eq!(reviewer_error.0, StatusCode::FORBIDDEN);
    assert!(
        read_revocation(temp.path(), "tenant-a", submission_id)
            .expect("tenant-a tombstone lookup succeeds")
            .is_none()
    );

    let owner_status = revoke_trace_handler(
        State(state),
        auth_headers("token-a"),
        AxumPath(submission_id),
    )
    .await
    .expect("owner self-revocation remains available");
    assert_eq!(owner_status, StatusCode::NO_CONTENT);
    assert!(
        read_revocation(temp.path(), "tenant-a", submission_id)
            .expect("tenant-a tombstone lookup succeeds")
            .is_some()
    );
}

#[tokio::test]
async fn privileged_revocation_requires_explicit_reason_after_source_abac() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    let submission_id = envelope.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        Json(envelope),
    )
    .await
    .expect("submission succeeds");

    let error = revoke_trace_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        AxumPath(submission_id),
    )
    .await
    .expect_err("privileged revocation requires a reason");
    assert_eq!(error.0, StatusCode::BAD_REQUEST);
    assert!(
        read_revocation(temp.path(), "tenant-a", submission_id)
            .expect("tenant-a tombstone lookup succeeds")
            .is_none()
    );
    let record = read_submission_record(temp.path(), "tenant-a", submission_id)
        .expect("submission record reads")
        .expect("submission record exists");
    assert_eq!(record.status, TraceCorpusStatus::Accepted);
}

