#[tokio::test]
async fn export_worker_retry_failed_jobs_applies_backoff_and_retry_limits() {
    let Some(backend) = postgres_backend_for_ingest_test().await else {
        return;
    };
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-b").await;

    let temp = tempfile::tempdir().expect("temp dir");
    let db_mirror: Arc<dyn Database> = backend.clone();
    let state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        false,
        false,
        false,
    );
    let now = Utc::now();
    let retryable_job_id = Uuid::new_v4();
    let not_due_job_id = Uuid::new_v4();
    let limit_job_id = Uuid::new_v4();
    let unsafe_job_id = Uuid::new_v4();
    let tenant_b_job_id = Uuid::new_v4();
    let tenant_b_grant_id = Uuid::new_v4();
    for (export_job_id, purpose, finished_at, retry_count, replayable_metadata) in [
        (
            retryable_job_id,
            "retry due replay",
            now - Duration::seconds(90),
            Some(1),
            true,
        ),
        (
            not_due_job_id,
            "retry not due replay",
            now - Duration::seconds(5),
            Some(0),
            true,
        ),
        (
            limit_job_id,
            "retry limit replay",
            now - Duration::minutes(10),
            Some(2),
            true,
        ),
        (
            unsafe_job_id,
            "retry unsafe replay",
            now - Duration::minutes(10),
            None,
            false,
        ),
    ] {
        let grant_id = Uuid::new_v4();
        backend
            .upsert_trace_export_access_grant(StorageTraceExportAccessGrantWrite {
                tenant_id: "tenant-a".to_string(),
                export_job_id,
                grant_id,
                caller_principal_ref: principal_storage_ref("export-worker-token-a"),
                requested_dataset_kind: TraceExportDatasetKind::ReplayDataset
                    .storage_name()
                    .to_string(),
                purpose: purpose.to_string(),
                max_item_cap: Some(5),
                status: StorageTraceExportAccessGrantStatus::Active,
                requested_at: now - Duration::minutes(15),
                expires_at: now + Duration::minutes(30),
                metadata: BTreeMap::from([("grant_type".to_string(), "queued".to_string())]),
            })
            .await
            .expect("export grant writes");
        let mut metadata = if replayable_metadata {
            export_job_request_metadata(
                Some(5),
                Some(TraceCorpusStatus::Accepted),
                Some(ResidualPiiRisk::Low),
                Some(ConsentScope::DebuggingEvaluation),
                None,
            )
        } else {
            BTreeMap::new()
        };
        metadata.insert("state".to_string(), "failed".to_string());
        if let Some(retry_count) = retry_count {
            metadata.insert("retry_count".to_string(), retry_count.to_string());
        }
        backend
            .upsert_trace_export_job(StorageTraceExportJobWrite {
                tenant_id: "tenant-a".to_string(),
                export_job_id,
                grant_id,
                caller_principal_ref: principal_storage_ref("export-worker-token-a"),
                requested_dataset_kind: TraceExportDatasetKind::ReplayDataset
                    .storage_name()
                    .to_string(),
                purpose: purpose.to_string(),
                max_item_cap: Some(5),
                status: StorageTraceExportJobStatus::Failed,
                requested_at: now - Duration::minutes(15),
                started_at: Some(finished_at - Duration::minutes(1)),
                finished_at: Some(finished_at),
                expires_at: now + Duration::minutes(30),
                result_manifest_id: None,
                item_count: None,
                last_error: Some(
                    "queued_export_job_execution_failed;reason_hash=sha256:old".to_string(),
                ),
                metadata,
            })
            .await
            .expect("failed export job writes");
    }
    backend
        .upsert_trace_export_access_grant(StorageTraceExportAccessGrantWrite {
            tenant_id: "tenant-b".to_string(),
            export_job_id: tenant_b_job_id,
            grant_id: tenant_b_grant_id,
            caller_principal_ref: principal_storage_ref("export-worker-token-b"),
            requested_dataset_kind: TraceExportDatasetKind::ReplayDataset
                .storage_name()
                .to_string(),
            purpose: "tenant-b retry due replay".to_string(),
            max_item_cap: Some(5),
            status: StorageTraceExportAccessGrantStatus::Active,
            requested_at: now - Duration::minutes(15),
            expires_at: now + Duration::minutes(30),
            metadata: BTreeMap::from([("grant_type".to_string(), "queued".to_string())]),
        })
        .await
        .expect("tenant-b export grant writes");
    let mut tenant_b_metadata = export_job_request_metadata(
        Some(5),
        Some(TraceCorpusStatus::Accepted),
        Some(ResidualPiiRisk::Low),
        Some(ConsentScope::DebuggingEvaluation),
        None,
    );
    tenant_b_metadata.insert("state".to_string(), "failed".to_string());
    tenant_b_metadata.insert("retry_count".to_string(), "1".to_string());
    backend
        .upsert_trace_export_job(StorageTraceExportJobWrite {
            tenant_id: "tenant-b".to_string(),
            export_job_id: tenant_b_job_id,
            grant_id: tenant_b_grant_id,
            caller_principal_ref: principal_storage_ref("export-worker-token-b"),
            requested_dataset_kind: TraceExportDatasetKind::ReplayDataset
                .storage_name()
                .to_string(),
            purpose: "tenant-b retry due replay".to_string(),
            max_item_cap: Some(5),
            status: StorageTraceExportJobStatus::Failed,
            requested_at: now - Duration::minutes(15),
            started_at: Some(now - Duration::minutes(11)),
            finished_at: Some(now - Duration::minutes(10)),
            expires_at: now + Duration::minutes(30),
            result_manifest_id: None,
            item_count: None,
            last_error: Some(
                "queued_export_job_execution_failed;reason_hash=sha256:tenant-b".to_string(),
            ),
            metadata: tenant_b_metadata,
        })
        .await
        .expect("tenant-b failed export job writes");

    let Json(retry_response) = worker_export_jobs_retry_failed_handler(
        State(state.clone()),
        auth_headers("export-worker-token-a"),
        Json(TraceExportJobsRetryFailedRequest {
            dataset_kind: Some("replay_dataset".to_string()),
            max_jobs: Some(5),
            max_retry_count: Some(2),
            base_delay_seconds: Some(30),
            max_delay_seconds: Some(120),
            reason: None,
        }),
    )
    .await
    .expect("worker retries due failed jobs");
    assert_eq!(retry_response.retried_count, 1);
    assert_eq!(retry_response.skipped_not_due_count, 1);
    assert_eq!(retry_response.skipped_ineligible_count, 2);
    assert_eq!(retry_response.failed_after_count, 3);
    assert_eq!(
        retry_response.retried_jobs[0].export_job_id,
        retryable_job_id
    );
    assert_eq!(
        retry_response.retried_jobs[0]
            .metadata
            .get("retry_count")
            .map(String::as_str),
        Some("2")
    );
    let tenant_b_jobs_after_retry = backend
        .list_trace_export_jobs("tenant-b")
        .await
        .expect("tenant-b jobs read after retry");
    let tenant_b_job_after_retry = tenant_b_jobs_after_retry
        .iter()
        .find(|job| job.export_job_id == tenant_b_job_id)
        .expect("tenant-b job remains after retry");
    assert_eq!(
        tenant_b_job_after_retry.status,
        StorageTraceExportJobStatus::Failed
    );

    let Json(run_response) = worker_export_jobs_run_queued_handler(
        State(state.clone()),
        auth_headers("export-worker-token-a"),
        Json(TraceExportJobsRunQueuedRequest {
            dataset_kind: Some("replay_dataset".to_string()),
            max_jobs: Some(1),
        }),
    )
    .await
    .expect("scheduler executes auto-retried job");
    assert_eq!(run_response.claimed_count, 1);
    assert_eq!(
        run_response.completed_jobs[0].export_job_id,
        retryable_job_id
    );

    let jobs = backend
        .list_trace_export_jobs("tenant-a")
        .await
        .expect("jobs list");
    let not_due = jobs
        .iter()
        .find(|job| job.export_job_id == not_due_job_id)
        .expect("not due job remains");
    assert_eq!(not_due.status, StorageTraceExportJobStatus::Failed);
    let retry_limited = jobs
        .iter()
        .find(|job| job.export_job_id == limit_job_id)
        .expect("retry limited job remains");
    assert_eq!(retry_limited.status, StorageTraceExportJobStatus::Failed);
    let unsafe_job = jobs
        .iter()
        .find(|job| job.export_job_id == unsafe_job_id)
        .expect("unsafe job remains");
    assert_eq!(unsafe_job.status, StorageTraceExportJobStatus::Failed);
    let tenant_b_jobs_after_run = backend
        .list_trace_export_jobs("tenant-b")
        .await
        .expect("tenant-b jobs read after run");
    let tenant_b_job_after_run = tenant_b_jobs_after_run
        .iter()
        .find(|job| job.export_job_id == tenant_b_job_id)
        .expect("tenant-b job remains after run");
    assert_eq!(
        tenant_b_job_after_run.status,
        StorageTraceExportJobStatus::Failed
    );

    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-b").await;
}

#[tokio::test]
async fn export_job_scheduler_tick_retries_due_failures_then_runs_queued_jobs() {
    let Some(backend) = postgres_backend_for_ingest_test().await else {
        return;
    };
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-b").await;

    let temp = tempfile::tempdir().expect("temp dir");
    let db_mirror: Arc<dyn Database> = backend.clone();
    let state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        false,
        false,
        false,
    );
    let now = Utc::now();
    let failed_job_id = Uuid::new_v4();
    let queued_job_id = Uuid::new_v4();
    let tenant_b_failed_job_id = Uuid::new_v4();
    let tenant_b_grant_id = Uuid::new_v4();
    for (export_job_id, status, purpose, finished_at, metadata) in [
        (
            failed_job_id,
            StorageTraceExportJobStatus::Failed,
            "scheduler due failed replay",
            Some(now - Duration::seconds(90)),
            {
                let mut metadata = export_job_request_metadata(
                    Some(5),
                    Some(TraceCorpusStatus::Accepted),
                    Some(ResidualPiiRisk::Low),
                    Some(ConsentScope::DebuggingEvaluation),
                    None,
                );
                metadata.insert("state".to_string(), "failed".to_string());
                metadata
            },
        ),
        (
            queued_job_id,
            StorageTraceExportJobStatus::Queued,
            "scheduler queued replay",
            None,
            export_job_request_metadata(
                Some(5),
                Some(TraceCorpusStatus::Accepted),
                Some(ResidualPiiRisk::Low),
                Some(ConsentScope::DebuggingEvaluation),
                None,
            ),
        ),
    ] {
        let grant_id = Uuid::new_v4();
        backend
            .upsert_trace_export_access_grant(StorageTraceExportAccessGrantWrite {
                tenant_id: "tenant-a".to_string(),
                export_job_id,
                grant_id,
                caller_principal_ref: principal_storage_ref("export-worker-token-a"),
                requested_dataset_kind: TraceExportDatasetKind::ReplayDataset
                    .storage_name()
                    .to_string(),
                purpose: purpose.to_string(),
                max_item_cap: Some(5),
                status: StorageTraceExportAccessGrantStatus::Active,
                requested_at: now - Duration::minutes(15),
                expires_at: now + Duration::minutes(30),
                metadata: BTreeMap::from([("grant_type".to_string(), "queued".to_string())]),
            })
            .await
            .expect("export grant writes");
        backend
            .upsert_trace_export_job(StorageTraceExportJobWrite {
                tenant_id: "tenant-a".to_string(),
                export_job_id,
                grant_id,
                caller_principal_ref: principal_storage_ref("export-worker-token-a"),
                requested_dataset_kind: TraceExportDatasetKind::ReplayDataset
                    .storage_name()
                    .to_string(),
                purpose: purpose.to_string(),
                max_item_cap: Some(5),
                status,
                requested_at: now - Duration::minutes(15),
                started_at: finished_at.map(|finished_at| finished_at - Duration::minutes(1)),
                finished_at,
                expires_at: now + Duration::minutes(30),
                result_manifest_id: None,
                item_count: None,
                last_error: (status == StorageTraceExportJobStatus::Failed).then(|| {
                    "queued_export_job_execution_failed;reason_hash=sha256:old".to_string()
                }),
                metadata,
            })
            .await
            .expect("export job writes");
    }
    backend
        .upsert_trace_export_access_grant(StorageTraceExportAccessGrantWrite {
            tenant_id: "tenant-b".to_string(),
            export_job_id: tenant_b_failed_job_id,
            grant_id: tenant_b_grant_id,
            caller_principal_ref: principal_storage_ref("export-worker-token-b"),
            requested_dataset_kind: TraceExportDatasetKind::ReplayDataset
                .storage_name()
                .to_string(),
            purpose: "tenant-b scheduler due failed replay".to_string(),
            max_item_cap: Some(5),
            status: StorageTraceExportAccessGrantStatus::Active,
            requested_at: now - Duration::minutes(15),
            expires_at: now + Duration::minutes(30),
            metadata: BTreeMap::from([("grant_type".to_string(), "queued".to_string())]),
        })
        .await
        .expect("tenant-b export grant writes");
    let mut tenant_b_metadata = export_job_request_metadata(
        Some(5),
        Some(TraceCorpusStatus::Accepted),
        Some(ResidualPiiRisk::Low),
        Some(ConsentScope::DebuggingEvaluation),
        None,
    );
    tenant_b_metadata.insert("state".to_string(), "failed".to_string());
    backend
        .upsert_trace_export_job(StorageTraceExportJobWrite {
            tenant_id: "tenant-b".to_string(),
            export_job_id: tenant_b_failed_job_id,
            grant_id: tenant_b_grant_id,
            caller_principal_ref: principal_storage_ref("export-worker-token-b"),
            requested_dataset_kind: TraceExportDatasetKind::ReplayDataset
                .storage_name()
                .to_string(),
            purpose: "tenant-b scheduler due failed replay".to_string(),
            max_item_cap: Some(5),
            status: StorageTraceExportJobStatus::Failed,
            requested_at: now - Duration::minutes(15),
            started_at: Some(now - Duration::seconds(150)),
            finished_at: Some(now - Duration::seconds(90)),
            expires_at: now + Duration::minutes(30),
            result_manifest_id: None,
            item_count: None,
            last_error: Some(
                "queued_export_job_execution_failed;reason_hash=sha256:tenant-b".to_string(),
            ),
            metadata: tenant_b_metadata,
        })
        .await
        .expect("tenant-b export job writes");

    let summary = run_trace_export_job_scheduler_tick(
        state,
        &TraceExportJobSchedulerConfig {
            worker_token: SecretString::from("export-worker-token-a".to_string()),
            interval: StdDuration::from_secs(60),
            dataset_kind: Some("replay_dataset".to_string()),
            run_queued_max_jobs: 5,
            retry_failed_max_jobs: 5,
            retry_failed_max_retry_count: 3,
            retry_failed_base_delay_seconds: 30,
            retry_failed_max_delay_seconds: 120,
            retry_failed_reason: "scheduled export retry".to_string(),
        },
    )
    .await
    .expect("scheduler tick runs through worker auth and handlers");

    assert_eq!(summary.retry_failed.retried_count, 1);
    assert_eq!(summary.run_queued.claimed_count, 2);
    assert_eq!(summary.run_queued.completed_count, 2);
    assert_eq!(summary.run_queued.failed_count, 0);
    assert_eq!(summary.run_queued.pending_after_count, 0);
    assert_eq!(
        summary
            .run_queued
            .completed_jobs
            .iter()
            .map(|job| job.export_job_id)
            .collect::<BTreeSet<_>>(),
        BTreeSet::from([failed_job_id, queued_job_id])
    );
    let tenant_b_jobs = backend
        .list_trace_export_jobs("tenant-b")
        .await
        .expect("tenant-b jobs read after scheduler tick");
    let tenant_b_failed_job = tenant_b_jobs
        .iter()
        .find(|job| job.export_job_id == tenant_b_failed_job_id)
        .expect("tenant-b failed job remains");
    assert_eq!(
        tenant_b_failed_job.status,
        StorageTraceExportJobStatus::Failed
    );

    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-b").await;
}

