#[test]
fn export_job_slice_keeps_safe_request_metadata_for_status_updates() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let tenant =
        authenticate(state.as_ref(), &auth_headers("review-token-a")).expect("reviewer auth");
    let now = Utc::now();
    let grant = TraceExportAccessGrant {
        grant_id: Uuid::new_v4(),
        tenant_id: tenant.tenant_id.clone(),
        caller_principal_ref: tenant.principal_ref.clone(),
        requested_dataset_kind: TraceExportDatasetKind::BenchmarkConversion,
        purpose: "metadata_unit".to_string(),
        expires_at: now + Duration::minutes(5),
        max_item_cap: 10,
        status: TraceExportGrantStatus::Active,
    };
    let raw_external_ref = "frontier-lab:request-ticket-99";
    let job = create_validated_export_job_slice(
        state.as_ref(),
        &tenant,
        TraceExportJobRequest {
            requested_dataset_kind: TraceExportDatasetKind::BenchmarkConversion,
            purpose: "metadata_unit".to_string(),
            requested_limit: Some(4),
            grant,
            metadata: export_job_request_metadata(
                Some(4),
                Some(TraceCorpusStatus::Accepted),
                Some(ResidualPiiRisk::Low),
                Some(ConsentScope::BenchmarkOnly),
                Some(raw_external_ref),
            ),
        },
        now,
    )
    .expect("job slice validates");

    assert_eq!(
        job.metadata
            .get("request_schema_version")
            .map(String::as_str),
        Some("trace_export_job_request.v1")
    );
    assert_eq!(
        job.metadata.get("filter_consent_scope").map(String::as_str),
        Some("benchmark_only")
    );
    assert_eq!(
        job.metadata.get("external_ref_hash").map(String::as_str),
        Some(sha256_prefixed(raw_external_ref).as_str())
    );
    let completed_metadata = export_job_status_metadata(&job, "completed");
    assert_eq!(
        completed_metadata.get("state").map(String::as_str),
        Some("completed")
    );
    assert_eq!(
        completed_metadata
            .get("filter_consent_scope")
            .map(String::as_str),
        Some("benchmark_only")
    );
    assert_eq!(
        completed_metadata
            .get("external_ref_hash")
            .map(String::as_str),
        Some(sha256_prefixed(raw_external_ref).as_str())
    );
    let completed_json = serde_json::to_string(&completed_metadata).expect("metadata serializes");
    assert!(completed_json.contains(&sha256_prefixed(raw_external_ref)));
    assert!(!completed_json.contains(raw_external_ref));
}

#[tokio::test]
async fn revoked_traces_are_excluded_from_export_and_benchmark_with_manifest_artifacts() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let mut revoked = sample_envelope().await;
    make_metadata_only_low_risk(&mut revoked);
    revoked.trace_card.allowed_uses = vec![
        TraceAllowedUse::Evaluation,
        TraceAllowedUse::BenchmarkGeneration,
    ];
    let revoked_id = revoked.submission_id;
    let mut kept = sample_envelope().await;
    make_metadata_only_low_risk(&mut kept);
    kept.trace_card.allowed_uses = vec![
        TraceAllowedUse::Evaluation,
        TraceAllowedUse::BenchmarkGeneration,
    ];
    let kept_id = kept.submission_id;

    let _ = submit_trace_handler(State(state.clone()), auth_headers("token-a"), Json(revoked))
        .await
        .expect("revoked candidate submission succeeds");
    let _ = submit_trace_handler(State(state.clone()), auth_headers("token-a"), Json(kept))
        .await
        .expect("kept submission succeeds");
    revoke_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        AxumPath(revoked_id),
    )
    .await
    .expect("contributor can revoke own trace");

    let Json(export) = dataset_replay_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        Query(DatasetExportQuery {
            limit: Some(10),
            purpose: None,
            status: None,
            privacy_risk: None,
            consent_scope: None,
        }),
    )
    .await
    .expect("dataset export succeeds");
    assert_eq!(export.item_count, 1);
    assert_eq!(export.items[0].submission_id, kept_id);
    assert_eq!(export.manifest.source_submission_ids, vec![kept_id]);
    assert_eq!(export.manifest.audit_event_id, export.audit_event_id);
    assert!(
        export
            .manifest
            .source_submission_ids_hash
            .starts_with("sha256:")
    );
    assert!(!export.manifest.source_submission_ids.contains(&revoked_id));
    assert!(
        export_artifact_dir(temp.path(), "tenant-a", export.export_id)
            .join("manifest.json")
            .exists()
    );

    let Json(benchmark) = benchmark_convert_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        Json(BenchmarkConversionRequest {
            limit: Some(10),
            purpose: None,
            consent_scope: None,
            status: None,
            privacy_risk: None,
            external_ref: None,
        }),
    )
    .await
    .expect("benchmark conversion succeeds");
    assert_eq!(benchmark.item_count, 1);
    assert_eq!(benchmark.source_submission_ids, vec![kept_id]);
    assert!(benchmark.source_submission_ids_hash.starts_with("sha256:"));
    assert_eq!(benchmark.candidates[0].submission_id, kept_id);
    assert!(!benchmark.source_submission_ids.contains(&revoked_id));
    assert!(benchmark_artifact_path(temp.path(), "tenant-a", benchmark.conversion_id).exists());
    let credit_events =
        read_all_credit_events(temp.path(), "tenant-a").expect("credit events read");
    let benchmark_credit_events = credit_events
        .iter()
        .filter(|event| event.event_type == TraceCreditLedgerEventType::BenchmarkConversion)
        .collect::<Vec<_>>();
    assert_eq!(benchmark_credit_events.len(), 1);
    assert_eq!(benchmark_credit_events[0].submission_id, kept_id);
    assert_ne!(benchmark_credit_events[0].submission_id, revoked_id);

    let _ = benchmark_convert_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        Json(BenchmarkConversionRequest {
            limit: Some(10),
            purpose: None,
            consent_scope: None,
            status: None,
            privacy_risk: None,
            external_ref: None,
        }),
    )
    .await
    .expect("benchmark conversion rerun succeeds");
    let rerun_credit_events =
        read_all_credit_events(temp.path(), "tenant-a").expect("rerun credit events read");
    assert_eq!(
        rerun_credit_events
            .iter()
            .filter(|event| event.event_type == TraceCreditLedgerEventType::BenchmarkConversion)
            .count(),
        1,
        "benchmark conversion utility credit must be idempotent"
    );

    let audit_events = read_all_audit_events(temp.path(), "tenant-a").expect("audit events read");
    assert!(audit_events.iter().any(|event| {
        event.event_id == benchmark.audit_event_id
            && event.kind == "benchmark_conversion"
            && event.decision_inputs_hash == Some(benchmark.source_submission_ids_hash.clone())
    }));
}

#[tokio::test]
async fn benchmark_conversion_dedupes_exact_summary_duplicates_before_credit() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let mut original = sample_envelope().await;
    make_metadata_only_low_risk(&mut original);
    original.consent.scopes = vec![ConsentScope::BenchmarkOnly];
    original.trace_card.consent_scope = ConsentScope::BenchmarkOnly;
    original.trace_card.allowed_uses = vec![TraceAllowedUse::BenchmarkGeneration];
    let original_id = original.submission_id;

    let mut duplicate = sample_envelope().await;
    make_metadata_only_low_risk(&mut duplicate);
    duplicate.consent.scopes = vec![ConsentScope::BenchmarkOnly];
    duplicate.trace_card.consent_scope = ConsentScope::BenchmarkOnly;
    duplicate.trace_card.allowed_uses = vec![TraceAllowedUse::BenchmarkGeneration];
    duplicate.value.submission_score = 0.99;
    let duplicate_id = duplicate.submission_id;

    let mut distinct = sample_envelope().await;
    make_metadata_only_low_risk(&mut distinct);
    distinct.consent.scopes = vec![ConsentScope::BenchmarkOnly];
    distinct.trace_card.consent_scope = ConsentScope::BenchmarkOnly;
    distinct.trace_card.allowed_uses = vec![TraceAllowedUse::BenchmarkGeneration];
    distinct.value.submission_score = 0.10;
    for event in &mut distinct.events {
        if event.event_type
            == trace_commons_protocol::trace_contribution::TraceContributionEventType::UserMessage
        {
            event.redacted_content =
                Some("This benchmark source is intentionally distinct".to_string());
            break;
        }
    }
    let distinct_id = distinct.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        Json(original),
    )
    .await
    .expect("original benchmark submission succeeds");
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        Json(duplicate),
    )
    .await
    .expect("duplicate benchmark submission succeeds");
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        Json(distinct),
    )
    .await
    .expect("distinct benchmark submission succeeds");

    let derived = read_all_derived_records(temp.path(), "tenant-a").expect("derived reads");
    let original_hash = derived
        .iter()
        .find(|record| record.submission_id == original_id)
        .expect("original derived exists")
        .canonical_summary_hash
        .clone();
    let duplicate_derived = derived
        .iter()
        .find(|record| record.submission_id == duplicate_id)
        .expect("duplicate derived exists");
    let distinct_hash = derived
        .iter()
        .find(|record| record.submission_id == distinct_id)
        .expect("distinct derived exists")
        .canonical_summary_hash
        .clone();
    assert_eq!(duplicate_derived.canonical_summary_hash, original_hash);
    assert!(duplicate_derived.duplicate_score > 0.99);
    assert_ne!(distinct_hash, original_hash);

    let Json(benchmark) = benchmark_convert_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        Json(BenchmarkConversionRequest {
            limit: Some(2),
            purpose: Some("benchmark_dedupe_conversion".to_string()),
            consent_scope: Some("benchmark_only".to_string()),
            status: None,
            privacy_risk: None,
            external_ref: None,
        }),
    )
    .await
    .expect("reviewer can export de-duplicated benchmark artifact");

    assert_eq!(benchmark.item_count, 2);
    assert!(
        benchmark
            .candidates
            .iter()
            .any(|candidate| candidate.submission_id == original_id)
    );
    assert!(
        benchmark
            .candidates
            .iter()
            .any(|candidate| candidate.submission_id == distinct_id)
    );
    assert!(
        benchmark
            .candidates
            .iter()
            .all(|candidate| candidate.submission_id != duplicate_id)
    );

    let credit_events =
        read_all_credit_events(temp.path(), "tenant-a").expect("credit events read");
    let benchmark_credit_events = credit_events
        .iter()
        .filter(|event| event.event_type == TraceCreditLedgerEventType::BenchmarkConversion)
        .collect::<Vec<_>>();
    assert_eq!(benchmark_credit_events.len(), 2);
    assert!(
        benchmark_credit_events
            .iter()
            .any(|event| event.submission_id == original_id)
    );
    assert!(
        benchmark_credit_events
            .iter()
            .any(|event| event.submission_id == distinct_id)
    );
    assert!(
        benchmark_credit_events
            .iter()
            .all(|event| event.submission_id != duplicate_id)
    );
}

#[tokio::test]
async fn benchmark_conversion_writes_provenance_and_revocation_invalidates_it() {
    let temp = tempfile::tempdir().expect("temp dir");
    let mut state = test_state(temp.path().to_path_buf());
    let fake_submitter = FakeBenchmarkRegistrySubmitter::default();
    let submitted_calls = fake_submitter.calls.clone();
    Arc::make_mut(&mut state).benchmark_registry_submitter = Some(Arc::new(fake_submitter));
    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::BenchmarkOnly];
    envelope.trace_card.consent_scope = ConsentScope::BenchmarkOnly;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::BenchmarkGeneration];
    let submission_id = envelope.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        Json(envelope),
    )
    .await
    .expect("benchmark source submission succeeds");

    let Json(benchmark) = benchmark_convert_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        Json(BenchmarkConversionRequest {
            limit: Some(10),
            purpose: Some("provenance_benchmark".to_string()),
            consent_scope: None,
            status: None,
            privacy_risk: None,
            external_ref: Some("benchmark:provenance".to_string()),
        }),
    )
    .await
    .expect("benchmark conversion succeeds");
    let raw_summary = benchmark.candidates[0].canonical_summary.clone();

    let provenance_path = temp
        .path()
        .join("tenants")
        .join(tenant_storage_key("tenant-a"))
        .join("benchmarks")
        .join(benchmark.conversion_id.to_string())
        .join("provenance.json");
    let provenance: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(&provenance_path).expect("benchmark provenance reads"),
    )
    .expect("benchmark provenance parses");
    assert_eq!(provenance["tenant_id"], "tenant-a");
    assert_eq!(provenance["export_id"], benchmark.conversion_id.to_string());
    assert_eq!(provenance["purpose"], "provenance_benchmark");
    assert_eq!(
        provenance["source_submission_ids"][0],
        submission_id.to_string()
    );
    assert_eq!(
        provenance["source_submission_ids_hash"],
        benchmark.source_submission_ids_hash
    );
    assert!(provenance["invalidated_at"].is_null());

    let Json(published_benchmark) = benchmark_lifecycle_handler(
        State(state.clone()),
        auth_headers("benchmark-worker-token-a"),
        AxumPath(benchmark.conversion_id),
        Json(BenchmarkLifecycleUpdateRequest {
            registry: Some(TraceBenchmarkRegistryPatch {
                status: Some(TraceBenchmarkRegistryStatus::Published),
                registry_ref: Some("benchmark-registry:provenance".to_string()),
                published_at: Some(Utc::now()),
            }),
            evaluation: Some(TraceBenchmarkEvaluationPatch {
                status: Some(TraceBenchmarkEvaluationStatus::Passed),
                evaluator_ref: Some("evaluator:provenance".to_string()),
                evaluated_at: Some(Utc::now()),
                score: Some(1.0),
                pass_count: Some(1),
                fail_count: Some(0),
            }),
            reason: Some("published provenance benchmark".to_string()),
        }),
    )
    .await
    .expect("benchmark lifecycle publish succeeds");
    assert_eq!(
        published_benchmark.registry.status,
        TraceBenchmarkRegistryStatus::Published
    );

    revoke_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        AxumPath(submission_id),
    )
    .await
    .expect("contributor can revoke benchmark source");

    let invalidated: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(&provenance_path).expect("invalidated benchmark provenance reads"),
    )
    .expect("invalidated benchmark provenance parses");
    assert!(invalidated["invalidated_at"].as_str().is_some());
    assert_eq!(invalidated["invalidation_reason"], "contributor_revocation");

    let invalidated_artifact: TraceBenchmarkConversionArtifact = serde_json::from_str(
        &std::fs::read_to_string(benchmark_artifact_path(
            temp.path(),
            "tenant-a",
            benchmark.conversion_id,
        ))
        .expect("invalidated benchmark artifact reads"),
    )
    .expect("invalidated benchmark artifact parses");
    assert_eq!(
        invalidated_artifact.registry.status,
        TraceBenchmarkRegistryStatus::Revoked
    );
    assert!(invalidated_artifact.registry.revoked_at.is_some());
    assert_eq!(
        invalidated_artifact.registry.revocation_reason.as_deref(),
        Some("contributor_revocation")
    );
    assert_eq!(
        invalidated_artifact.evaluation.status,
        TraceBenchmarkEvaluationStatus::Inconclusive
    );
    assert!(
        invalidated_artifact
            .evaluation
            .last_update_reason
            .as_deref()
            .is_some_and(|reason| reason.contains("contributor_revocation"))
    );
    let audit_events = read_all_audit_events(temp.path(), "tenant-a").expect("audit events read");
    assert!(audit_events.iter().any(|event| {
        event.kind == "benchmark_lifecycle_update"
            && event.export_id == Some(benchmark.conversion_id)
            && event.reason.as_deref().is_some_and(|reason| {
                reason.contains("registry_status=revoked")
                    && reason.contains("evaluation_status=inconclusive")
            })
    }));

    let Json(after_revoke_summary) =
        operational_summary_handler(State(state.clone()), auth_headers("admin-token-a"))
            .await
            .expect("admin can inspect benchmark registry invalidation gap");
    assert_eq!(after_revoke_summary.benchmarks.published_count, 0);
    assert_eq!(after_revoke_summary.benchmarks.revoked_count, 1);
    assert_eq!(
        after_revoke_summary
            .benchmarks
            .external_registry_invalidation_gap_count,
        1
    );
    assert!(
        after_revoke_summary
            .benchmarks
            .blocker_reasons
            .contains(&"external_benchmark_registry_invalidation_gap=1".to_string())
    );
    assert!(
        after_revoke_summary
            .promotion_gates
            .blocking_gates
            .contains(
                &"revoked_benchmarks_waiting_for_external_registry_invalidation=1".to_string()
            )
    );

    let registry_outbox = read_all_benchmark_registry_outbox_items(temp.path(), "tenant-a")
        .expect("benchmark registry outbox reads after source revocation");
    assert_eq!(registry_outbox.len(), 2);
    let publish_item = registry_outbox
        .iter()
        .find(|item| item.operation == StorageTraceBenchmarkRegistryOutboxOperation::Publish)
        .expect("published benchmark keeps publish registry outbox item");
    let revoke_item = registry_outbox
        .iter()
        .find(|item| item.operation == StorageTraceBenchmarkRegistryOutboxOperation::Revoke)
        .expect("source invalidation enqueues revoke registry outbox item");
    assert_eq!(revoke_item.conversion_id, benchmark.conversion_id);
    assert_ne!(
        revoke_item.benchmark_outbox_id,
        publish_item.benchmark_outbox_id
    );
    assert_eq!(
        revoke_item.status,
        StorageTraceBenchmarkRegistryOutboxStatus::Pending
    );
    assert_eq!(revoke_item.registry_ref, "benchmark-registry:provenance");
    assert_eq!(
        revoke_item.source_submission_ids_hash,
        benchmark.source_submission_ids_hash
    );
    assert_eq!(
        revoke_item.evaluator_ref.as_deref(),
        Some("evaluator:provenance")
    );
    assert_eq!(revoke_item.evaluation_score, Some(1.0));
    assert!(revoke_item.artifact_payload_hash.starts_with("sha256:"));
    let outbox_json =
        std::fs::read_to_string(benchmark_registry_outbox_path(temp.path(), "tenant-a"))
            .expect("benchmark registry outbox file reads after source revocation");
    assert!(
        !outbox_json.contains(&raw_summary),
        "registry revoke outbox must not persist raw benchmark summary text"
    );

    let Json(submit_response) = benchmark_registry_outbox_submit_worker_handler(
        State(state.clone()),
        auth_headers("benchmark-worker-token-a"),
        Json(TraceBenchmarkRegistryOutboxSubmitWorkerRequest {
            purpose: Some("submit_revoked_benchmark_registry_items".to_string()),
            dry_run: false,
            limit: 10,
        }),
    )
    .await
    .expect("benchmark worker submits publish and revoke registry outbox items");
    assert_eq!(submit_response.checked, 2);
    assert_eq!(submit_response.submitted, 2);
    assert_eq!(submit_response.failed, 0);
    assert_eq!(submit_response.pending, 0);

    let calls = submitted_calls
        .lock()
        .expect("fake benchmark registry submitter calls lock");
    assert_eq!(calls.len(), 2);
    let revoke_call = calls
        .iter()
        .find(|call| call.operation == StorageTraceBenchmarkRegistryOutboxOperation::Revoke)
        .expect("registry submitter receives revoke operation");
    assert_eq!(revoke_call.conversion_id, benchmark.conversion_id);
    assert_eq!(revoke_call.registry_ref, "benchmark-registry:provenance");
    assert_eq!(
        revoke_call.source_submission_ids_hash,
        benchmark.source_submission_ids_hash
    );
    assert_eq!(
        revoke_call.evaluator_ref.as_deref(),
        Some("evaluator:provenance")
    );
    assert_eq!(revoke_call.evaluation_score, Some(1.0));
    let revoke_call_json =
        serde_json::to_string(revoke_call).expect("revoke registry call serializes");
    assert!(!revoke_call_json.contains(&raw_summary));
}

#[tokio::test]
async fn benchmark_conversion_artifact_tracks_registry_and_evaluator_state() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        Json(envelope),
    )
    .await
    .expect("benchmark source submission succeeds");

    let Json(benchmark) = benchmark_convert_handler(
        State(state),
        auth_headers("review-token-a"),
        Json(BenchmarkConversionRequest {
            limit: Some(10),
            purpose: Some("registry_evaluator_contract".to_string()),
            consent_scope: None,
            status: None,
            privacy_risk: None,
            external_ref: Some("benchmark-registry:pending".to_string()),
        }),
    )
    .await
    .expect("benchmark conversion succeeds");

    assert_eq!(
        benchmark.artifact_schema_version,
        TRACE_BENCHMARK_CONVERSION_SCHEMA_VERSION
    );
    assert_eq!(
        benchmark.registry.status,
        TraceBenchmarkRegistryStatus::Candidate
    );
    assert!(benchmark.registry.registry_ref.is_none());
    assert!(benchmark.registry.published_at.is_none());
    assert_eq!(
        benchmark.evaluation.status,
        TraceBenchmarkEvaluationStatus::NotRun
    );
    assert!(benchmark.evaluation.evaluator_ref.is_none());
    assert!(benchmark.evaluation.evaluated_at.is_none());
    assert!(benchmark.evaluation.score.is_none());

    let artifact_path = benchmark_artifact_path(temp.path(), "tenant-a", benchmark.conversion_id);
    let persisted: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(artifact_path).expect("benchmark artifact reads"),
    )
    .expect("benchmark artifact parses");
    assert_eq!(
        persisted["artifact_schema_version"],
        TRACE_BENCHMARK_CONVERSION_SCHEMA_VERSION
    );
    assert_eq!(persisted["registry"]["status"], "candidate");
    assert_eq!(persisted["evaluation"]["status"], "not_run");
    assert!(persisted["registry"]["registry_ref"].is_null());
    assert!(persisted["evaluation"]["evaluator_ref"].is_null());
}

