#[tokio::test]
async fn postgres_rls_drill_records_readiness_smoke_evidence() {
    use axum::body::Body;
    use tower::ServiceExt;

    let Some(backend) = postgres_backend_for_ingest_test().await else {
        return;
    };
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;

    let temp = tempfile::tempdir().expect("temp dir");
    let db_mirror: Arc<dyn Database> = backend.clone();
    let state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        false,
        false,
        false,
    );

    let response = app(state.clone())
        .oneshot(
            axum::http::Request::builder()
                .method("POST")
                .uri("/v1/admin/postgres-rls-drill")
                .header(AUTHORIZATION, "Bearer admin-token-a")
                .header(CONTENT_TYPE, "application/json")
                .body(Body::from(
                    serde_json::json!({
                        "purpose": "operator PostgreSQL RLS drill",
                        "record_evidence": true
                    })
                    .to_string(),
                ))
                .expect("request builds"),
        )
        .await
        .expect("PostgreSQL RLS drill response");
    assert_eq!(response.status(), StatusCode::OK);
    let body = axum::body::to_bytes(response.into_body(), 16 * 1024)
        .await
        .expect("body reads");
    let value: serde_json::Value =
        serde_json::from_slice(&body).expect("PostgreSQL RLS drill response parses");
    let runtime_role_safe = !value["current_role_bypasses_rls"]
        .as_bool()
        .expect("bypass flag is bool")
        && !value["current_role_owns_trace_tables"]
            .as_bool()
            .expect("owner flag is bool");
    assert_eq!(value["ready"], serde_json::json!(runtime_role_safe));
    assert_eq!(
        value["production_ready"],
        serde_json::json!(runtime_role_safe)
    );
    assert_eq!(value["rls_ready"], serde_json::json!(runtime_role_safe));
    assert_eq!(value["force_rls_ready"], serde_json::json!(true));
    assert_eq!(
        value["tenant_context_transaction_local"],
        serde_json::json!(true)
    );
    assert!(
        value["current_role_hash"]
            .as_str()
            .expect("runtime role hash is string")
            .starts_with("sha256:")
    );
    assert_eq!(
        value["expected_runtime_role_hash_configured"],
        serde_json::json!(false)
    );
    assert_eq!(
        value["expected_runtime_role_hash_matched"],
        serde_json::Value::Null
    );
    assert!(
        value["expected_table_count"]
            .as_u64()
            .expect("expected table count is numeric")
            > 0
    );
    if runtime_role_safe {
        assert_eq!(value["blocking_gaps"], serde_json::json!([]));
    } else {
        assert!(
            value["blocking_gaps"]
                .as_array()
                .expect("blocking gaps is array")
                .iter()
                .any(|gap| gap == "current_role_bypasses_rls"
                    || gap == "current_role_owns_trace_tables")
        );
    }
    assert_eq!(
        value["recorded_evidence"]["check_name"],
        serde_json::json!("postgres_rls_readiness")
    );
    assert_eq!(
        value["recorded_evidence"]["status"],
        serde_json::json!(if runtime_role_safe {
            "passed"
        } else {
            "failed"
        })
    );
    assert!(
        value["evidence_hash"]
            .as_str()
            .expect("evidence hash is string")
            .starts_with("sha256:")
    );
    let body_text = std::str::from_utf8(&body).expect("body is utf8");
    assert!(!body_text.contains("admin-token-a"));
    assert!(
        read_all_audit_events(temp.path(), "tenant-a")
            .expect("file audit events remain after drill")
            .iter()
            .any(|event| {
                event.kind == "rollout_smoke_evidence"
                    && event.reason.as_deref().is_some_and(|reason| {
                        reason.contains("check_name=postgres_rls_readiness")
                            && reason.contains("status=passed")
                    })
            })
    );

    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
}

