#[tokio::test]
async fn admin_can_recover_stale_ranking_worker_run_as_failed() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let ranking_worker_run_id = Uuid::new_v4();
    append_ranking_worker_run(
        temp.path(),
        "tenant-a",
        &TraceRankingWorkerRunRecord {
            ranking_worker_run_id,
            tenant_id: "tenant-a".to_string(),
            tenant_storage_ref: tenant_storage_ref("tenant-a"),
            run_kind: TraceRankingWorkerRunKind::PredictionCredit,
            status: TraceRankingWorkerRunStatus::Running,
            dry_run: false,
            reason_hash: sha256_prefixed("dead prediction credit scheduler"),
            model_version: None,
            target_use: None,
            policy_version: None,
            limit: 25,
            checked_count: 3,
            succeeded_count: 1,
            skipped_existing_count: 1,
            skipped_model_risk_count: 1,
            skipped_ineligible_count: 0,
            pending_after_count: 5,
            result_refs: vec!["ranking_prediction:recovered-before-failure".to_string()],
            reason_counts: BTreeMap::from([("calibration_stale".to_string(), 1)]),
            actor_principal_ref: "utility-worker-a".to_string(),
            created_at: Utc::now()
                - Duration::hours(TRACE_RANKING_WORKER_RUN_STALE_AFTER_HOURS + 1),
            completed_at: None,
            last_error_hash: None,
        },
    )
    .expect("stale worker run writes");

    let Json(recovered) = recover_stale_ranking_worker_run_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        AxumPath(ranking_worker_run_id),
        Json(TraceRankingWorkerRunRecoveryRequest {
            reason: "scheduler pod was replaced".to_string(),
        }),
    )
    .await
    .expect("admin can recover stale ranking worker run");
    assert_eq!(recovered.ranking_worker_run_id, ranking_worker_run_id);
    assert_eq!(recovered.status, TraceRankingWorkerRunStatus::Failed);
    assert_eq!(recovered.checked_count, 3);
    assert_eq!(recovered.succeeded_count, 1);
    assert!(recovered.completed_at.is_some());
    assert!(recovered.last_error_hash.is_some());
    let recovered_json = serde_json::to_string(&recovered).expect("recovered serializes");
    assert!(!recovered_json.contains("scheduler pod was replaced"));

    let audit_events = read_all_audit_events(temp.path(), "tenant-a").expect("audit events read");
    let recovery_audit = audit_events
        .iter()
        .find(|event| event.kind == "ranking_worker_run_recovery")
        .expect("ranking worker run recovery writes audit event");
    let recovery_reason_hash = sha256_prefixed("scheduler pod was replaced");
    assert_eq!(recovery_audit.tenant_id, "tenant-a");
    assert_eq!(recovery_audit.submission_id, Uuid::nil());
    assert_eq!(recovery_audit.actor_role, Some(TokenRole::Admin));
    let expected_admin_principal_ref = principal_storage_ref("admin-token-a");
    assert_eq!(
        recovery_audit.actor_principal_ref.as_deref(),
        Some(expected_admin_principal_ref.as_str())
    );
    let expected_recovery_reason = format!(
        "ranking_worker_run_id={ranking_worker_run_id};run_kind=prediction_credit;status=failed;reason_hash={recovery_reason_hash}"
    );
    assert_eq!(
        recovery_audit.reason.as_deref(),
        Some(expected_recovery_reason.as_str())
    );
    let audit_json = serde_json::to_string(&audit_events).expect("audit events serialize");
    assert!(audit_json.contains(&recovery_reason_hash));
    assert!(!audit_json.contains("scheduler pod was replaced"));

    let raw_worker_runs: Vec<TraceRankingWorkerRunRecord> = read_jsonl_records(
        &ranking_worker_runs_path(temp.path(), "tenant-a"),
        "ranking worker run",
    )
    .expect("raw worker runs read");
    assert_eq!(raw_worker_runs.len(), 2);
    assert_eq!(
        raw_worker_runs[0].status,
        TraceRankingWorkerRunStatus::Running
    );
    assert_eq!(
        raw_worker_runs[1].status,
        TraceRankingWorkerRunStatus::Failed
    );

    let Json(operational) =
        operational_summary_handler(State(state.clone()), auth_headers("admin-token-a"))
            .await
            .expect("admin can inspect operational summary after recovery");
    let operational_json = serde_json::to_value(operational).expect("operational serializes");
    assert_eq!(
        operational_json["ranking"]["stale_running_worker_run_count"],
        serde_json::json!(0)
    );
    assert_eq!(
        operational_json["ranking"]["failed_worker_run_count"],
        serde_json::json!(1)
    );
    assert!(
        !operational_json["promotion_gates"]["blocking_gates"]
            .as_array()
            .expect("blocking gates array")
            .contains(&serde_json::json!("stale_ranking_worker_runs=1"))
    );
}

#[tokio::test]
async fn stale_ranking_worker_run_recovery_requires_admin_and_staleness() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let ranking_worker_run_id = Uuid::new_v4();
    append_ranking_worker_run(
        temp.path(),
        "tenant-a",
        &TraceRankingWorkerRunRecord {
            ranking_worker_run_id,
            tenant_id: "tenant-a".to_string(),
            tenant_storage_ref: tenant_storage_ref("tenant-a"),
            run_kind: TraceRankingWorkerRunKind::ModelPromotion,
            status: TraceRankingWorkerRunStatus::Running,
            dry_run: false,
            reason_hash: sha256_prefixed("fresh model promotion scheduler"),
            model_version: None,
            target_use: Some(TraceAllowedUse::RankingModelTraining),
            policy_version: None,
            limit: 25,
            checked_count: 0,
            succeeded_count: 0,
            skipped_existing_count: 0,
            skipped_model_risk_count: 0,
            skipped_ineligible_count: 0,
            pending_after_count: 0,
            result_refs: Vec::new(),
            reason_counts: BTreeMap::new(),
            actor_principal_ref: "utility-worker-a".to_string(),
            created_at: Utc::now(),
            completed_at: None,
            last_error_hash: None,
        },
    )
    .expect("fresh worker run writes");

    let utility_error = recover_stale_ranking_worker_run_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        AxumPath(ranking_worker_run_id),
        Json(TraceRankingWorkerRunRecoveryRequest {
            reason: "utility worker should not recover".to_string(),
        }),
    )
    .await
    .expect_err("utility workers cannot recover stale runs");
    assert_eq!(utility_error.0, StatusCode::FORBIDDEN);

    let fresh_error = recover_stale_ranking_worker_run_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        AxumPath(ranking_worker_run_id),
        Json(TraceRankingWorkerRunRecoveryRequest {
            reason: "fresh run should not be terminalized".to_string(),
        }),
    )
    .await
    .expect_err("fresh active runs cannot be recovered");
    assert_eq!(fresh_error.0, StatusCode::CONFLICT);
    assert_eq!(fresh_error.1.0.error, "ranking worker run is not stale");

    let raw_worker_runs =
        read_all_ranking_worker_runs(temp.path(), "tenant-a").expect("worker runs read");
    assert_eq!(raw_worker_runs.len(), 1);
    assert_eq!(
        raw_worker_runs[0].status,
        TraceRankingWorkerRunStatus::Running
    );
}

#[tokio::test]
async fn ranking_prediction_credit_worker_run_records_failed_status_on_fatal_error() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let Json(candidate) = ranking_model_version_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceRankingModelVersionRequest {
            model_version: "trace-ranker-credit-failed-run-v1".to_string(),
            feature_schema_version: "ranking-features-credit-failed-run-v1".to_string(),
            policy_version: "trace-credit-policy-v1".to_string(),
            status: StorageTraceRankingModelStatus::Candidate,
            training_dataset_hash: sha256_prefixed("ranking-training-credit-failed-run"),
            calibration_dataset_hash: sha256_prefixed("ranking-calibration-credit-failed-run"),
            model_artifact_hash: sha256_prefixed("ranking-model-artifact-credit-failed-run"),
        }),
    )
    .await
    .expect("admin can stage candidate ranking model");

    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::RankingTraining];
    envelope.trace_card.consent_scope = ConsentScope::RankingTraining;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::RankingModelTraining];
    let submission_id = envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        Json(envelope),
    )
    .await
    .expect("ranking submission succeeds");
    let Json(feature) = ranking_feature_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceRankingFeatureRequest {
            submission_id,
            target_use: TraceAllowedUse::RankingModelTraining,
            feature_schema_version: candidate.feature_schema_version.clone(),
            feature_vector_hash: sha256_prefixed("ranking-feature-credit-failed-run"),
            feature_names_hash: sha256_prefixed("ranking-feature-names-credit-failed-run"),
            source_feature_hash: sha256_prefixed("ranking-source-feature-credit-failed-run"),
            duplicate_score: Some(0.05),
            novelty_score: Some(0.91),
            privacy_risk_score: Some(0.02),
            quality_score: Some(0.88),
            coverage_tags: vec!["tool:terminal".to_string()],
        }),
    )
    .await
    .expect("utility worker can write ranking feature");
    let Json(_) = ranking_prediction_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceRankingPredictionRequest {
            submission_id,
            target_use: TraceAllowedUse::RankingModelTraining,
            model_version: candidate.model_version.clone(),
            feature_schema_version: candidate.feature_schema_version.clone(),
            prediction_policy_version: candidate.policy_version.clone(),
            feature_vector_hash: feature.feature_vector_hash,
            predicted_utility_micros: 1_250_000,
            uncertainty_micros: 250_000,
            confidence: 0.9,
            risk_penalty_micros: 0,
            novelty_bonus_micros: 0,
            explanation_codes: vec!["ranking_pair_utility".to_string()],
        }),
    )
    .await
    .expect("utility worker can write ranking prediction");

    let credit_path = credit_ledger_path(temp.path(), "tenant-a");
    std::fs::create_dir_all(
        credit_path
            .parent()
            .expect("credit ledger path has parent directory"),
    )
    .expect("credit ledger dir writes");
    std::fs::write(&credit_path, "{not-json").expect("malformed credit ledger writes");

    let error = ranking_prediction_credit_run_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceRankingPredictionCreditRunRequest {
            dry_run: false,
            allow_at_risk_models: false,
            reason: "scheduled ranking prediction credit fatal path".to_string(),
            limit: Some(1),
            model_version: None,
            target_use: None,
            policy_version: None,
        }),
    )
    .await
    .expect_err("fatal read error fails the worker run");
    assert_eq!(error.0, StatusCode::INTERNAL_SERVER_ERROR);

    let Json(worker_runs) =
        ranking_worker_runs_handler(State(state.clone()), auth_headers("admin-token-a"))
            .await
            .expect("admin can list failed ranking worker run");
    assert_eq!(worker_runs.len(), 1);
    assert_eq!(
        worker_runs[0].run_kind,
        TraceRankingWorkerRunKind::PredictionCredit
    );
    assert_eq!(worker_runs[0].status, TraceRankingWorkerRunStatus::Failed);
    assert_eq!(worker_runs[0].checked_count, 0);
    assert_eq!(worker_runs[0].succeeded_count, 0);
    assert!(worker_runs[0].completed_at.is_some());
    let expected_error_hash = sha256_prefixed("status=500;error=trace commons operation failed");
    assert_eq!(
        worker_runs[0].last_error_hash.as_deref(),
        Some(expected_error_hash.as_str())
    );

    let raw_worker_runs: Vec<TraceRankingWorkerRunRecord> = read_jsonl_records(
        &ranking_worker_runs_path(temp.path(), "tenant-a"),
        "ranking worker run",
    )
    .expect("raw worker runs read");
    assert_eq!(raw_worker_runs.len(), 2);
    assert_eq!(
        raw_worker_runs[0].ranking_worker_run_id,
        raw_worker_runs[1].ranking_worker_run_id
    );
    assert_eq!(
        raw_worker_runs[0].status,
        TraceRankingWorkerRunStatus::Running
    );
    assert_eq!(
        raw_worker_runs[1].status,
        TraceRankingWorkerRunStatus::Failed
    );
    assert_eq!(
        raw_worker_runs[1].last_error_hash.as_deref(),
        Some(expected_error_hash.as_str())
    );
}

