#[tokio::test]
async fn ranking_model_promotion_rejects_holdout_below_calibration_floor() {
    let temp = tempfile::tempdir().expect("temp dir");
    let mut state = test_state(temp.path().to_path_buf());
    let (candidate, prediction) =
        seed_credit_cycle_ready_candidate(state.clone(), "trace-ranker-holdout-floor-v1").await;
    let Json(_) = ranking_label_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        Json(TraceRankingLabelRequest {
            submission_id: prediction.submission_id,
            target_use: TraceAllowedUse::RankingModelTraining,
            label_source: StorageTraceRankingLabelSource::Reviewer,
            utility_category: StorageTraceRankingUtilityCategory::RankingTraining,
            label_outcome: StorageTraceRankingLabelOutcome::Useful,
            utility_delta_micros: 1_250_000,
            evidence_hash: sha256_prefixed("ranking-review-evidence-holdout-floor"),
            external_ref: "private-ranking-review-holdout-floor".to_string(),
        }),
    )
    .await
    .expect("reviewer can write second calibration label");
    let Json(calibration) = ranking_calibration_run_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceRankingCalibrationRunRequest {
            model_version: candidate.model_version.clone(),
            target_use: TraceAllowedUse::RankingModelTraining,
            policy_version: candidate.policy_version.clone(),
            evaluation_dataset_hash: candidate.calibration_dataset_hash.clone(),
            min_label_count: Some(2),
            confidence_threshold: Some(0.5),
            max_average_absolute_error_micros: Some(100_000),
        }),
    )
    .await
    .expect("utility worker can persist calibration with a raised sample floor");
    assert!(calibration.promotable);
    assert_eq!(calibration.min_label_count, 2);
    assert_eq!(calibration.joined_label_prediction_count, 2);

    Arc::make_mut(&mut state).ranking_require_calibration_dataset_registry = true;
    let Json(_) = ranking_calibration_dataset_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceRankingCalibrationDatasetRequest {
            calibration_dataset_hash: candidate.calibration_dataset_hash.clone(),
            target_use: TraceAllowedUse::RankingModelTraining,
            policy_version: candidate.policy_version.clone(),
            source_manifest_hash: sha256_prefixed("holdout-floor-manifest"),
            source_count: 1,
            label_source_count: 2,
            label_actor_count: 2,
            status: StorageTraceRankingCalibrationDatasetStatus::Candidate,
        }),
    )
    .await
    .expect("admin can register undersized calibration holdout metadata");

    let error = ranking_model_promotion_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceRankingModelPromotionRequest {
            dry_run: false,
            model_version: candidate.model_version.clone(),
            target_use: TraceAllowedUse::RankingModelTraining,
            policy_version: candidate.policy_version.clone(),
            reason: "undersized registered holdout should block promotion".to_string(),
        }),
    )
    .await
    .expect_err("promotion enforces the calibration run sample floor on holdout metadata");
    assert_eq!(error.0, StatusCode::CONFLICT);
    assert!(
        error
            .1
            .0
            .error
            .contains("source_count below configured threshold")
    );

    let model_versions =
        read_all_ranking_model_versions(temp.path(), "tenant-a").expect("model versions read");
    let latest = latest_ranking_model_version(&model_versions, &candidate.model_version).unwrap();
    assert_eq!(latest.status, StorageTraceRankingModelStatus::Candidate);
}

