#[tokio::test]
async fn credit_cycle_scheduler_runs_next_eligible_model() {
    let temp = tempfile::tempdir().expect("temp dir");
    let mut state = test_state(temp.path().to_path_buf());
    Arc::make_mut(&mut state).near_credit_submitter =
        Some(Arc::new(FakeNearCreditSubmitter::default()));
    Arc::make_mut(&mut state).near_credit_confirmer =
        Some(Arc::new(FakeNearCreditConfirmer::default()));
    let (candidate, prediction) =
        seed_credit_cycle_ready_candidate(state.clone(), "trace-ranker-credit-cycle-sched-v1")
            .await;

    let mut tenant_b_envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut tenant_b_envelope);
    tenant_b_envelope.consent.scopes = vec![ConsentScope::ModelTraining];
    tenant_b_envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
    tenant_b_envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let tenant_b_submission_id = tenant_b_envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-b"),
        Json(tenant_b_envelope),
    )
    .await
    .expect("tenant-b training submission succeeds");
    let Json(_) = append_credit_event_handler(
        State(state.clone()),
        auth_headers("review-token-b"),
        AxumPath(tenant_b_submission_id),
        Json(TraceCreditLedgerAppendRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 2.0,
            reason: Some("tenant-b utility outside scheduled tenant-a credit cycle".to_string()),
            external_ref: Some("frontier:tenant-b-credit-cycle-scheduler-boundary".to_string()),
        }),
    )
    .await
    .expect("tenant-b reviewer can append training credit");

    let Json(scheduler) = credit_cycle_scheduler_run_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceCreditCycleSchedulerRunRequest {
            dry_run: false,
            preflight_only: false,
            submit_near_outbox: true,
            confirm_near_outbox: true,
            target_use: TraceAllowedUse::RankingModelTraining,
            model_version: None,
            policy_version: Some(candidate.policy_version.clone()),
            reason: "scheduled next eligible credit cycle".to_string(),
            issuer_approval_evidence_hash: None,
            near_contract_id: Some("trace-credits.testnet".to_string()),
            limit: Some(1),
            calibration_limit: Some(10),
            model_promotion_limit: Some(10),
            prediction_credit_limit: Some(10),
            credit_settlement_limit: Some(10),
            near_outbox_limit: Some(10),
            near_outbox_confirm_limit: Some(10),
            min_label_count: Some(1),
            confidence_threshold: Some(0.5),
            max_average_absolute_error_micros: Some(100_000),
            allow_at_risk_models: false,
        }),
    )
    .await
    .expect("scheduler runs next eligible credit cycle");

    assert_eq!(scheduler.checked_count, 1);
    assert_eq!(scheduler.started_count, 1);
    assert_eq!(scheduler.skipped_active_count, 0);
    assert_eq!(scheduler.skipped_count, 0);
    assert_eq!(scheduler.cycles.len(), 1);
    assert_eq!(scheduler.cycles[0].model_version, candidate.model_version);
    assert_eq!(scheduler.cycles[0].prediction_credit.credited_count, 1);
    assert_eq!(scheduler.cycles[0].settlement.settled_source_event_count, 1);
    assert_eq!(scheduler.cycles[0].near_outbox_submit.submitted, 1);
    assert_eq!(scheduler.cycles[0].near_outbox_confirm.confirmed, 1);

    let credit_events = read_all_credit_events(temp.path(), "tenant-a")
        .expect("credit events read after scheduled cycle");
    assert!(credit_events.iter().any(|event| {
        event.external_ref.as_deref()
            == Some(&format!(
                "ranking_prediction:{}",
                prediction.ranking_prediction_id
            ))
    }));
    let worker_runs =
        read_all_ranking_worker_runs(temp.path(), "tenant-a").expect("worker runs read");
    assert_eq!(
        worker_runs
            .iter()
            .filter(|run| run.run_kind == TraceRankingWorkerRunKind::CreditCycle)
            .count(),
        1
    );
    assert!(
        read_all_credit_settlement_batches(temp.path(), "tenant-b")
            .expect("tenant-b settlement batches read")
            .is_empty()
    );
    assert!(
        read_all_near_credit_outbox_items(temp.path(), "tenant-b")
            .expect("tenant-b outbox reads")
            .is_empty()
    );
}

#[tokio::test]
async fn credit_cycle_scheduler_preflight_only_reports_eligible_without_side_effects() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let (candidate, _) =
        seed_credit_cycle_ready_candidate(state.clone(), "trace-ranker-credit-cycle-preflight-v1")
            .await;
    let request = serde_json::from_value(serde_json::json!({
        "dry_run": true,
        "preflight_only": true,
        "submit_near_outbox": false,
        "target_use": "ranking_model_training",
        "policy_version": candidate.policy_version,
        "reason": "preview next eligible credit cycle",
        "near_contract_id": "trace-credits.testnet",
        "limit": 1,
        "calibration_limit": 10,
        "model_promotion_limit": 10,
        "prediction_credit_limit": 10,
        "credit_settlement_limit": 10,
        "near_outbox_limit": 10,
        "min_label_count": 1,
        "confidence_threshold": 0.5,
        "max_average_absolute_error_micros": 100000,
        "allow_at_risk_models": false
    }))
    .expect("preflight-only request deserializes");

    let Json(scheduler) = credit_cycle_scheduler_run_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(request),
    )
    .await
    .expect("scheduler preflight reports eligible candidate");

    let scheduler_value = serde_json::to_value(&scheduler).expect("scheduler response serializes");
    assert_eq!(scheduler.checked_count, 1);
    assert_eq!(scheduler.started_count, 0);
    assert_eq!(scheduler.skipped_count, 0);
    assert_eq!(scheduler_value["preflight_only"].as_bool(), Some(true));
    assert_eq!(scheduler_value["eligible_count"].as_u64(), Some(1));
    assert_eq!(
        scheduler_value["decisions"][0]["action"].as_str(),
        Some("eligible")
    );
    assert_eq!(
        scheduler_value["decisions"][0]["model_version"].as_str(),
        Some("trace-ranker-credit-cycle-preflight-v1")
    );
    assert!(scheduler_value["decisions"][0]["skip_reason"].is_null());
    assert!(scheduler.cycles.is_empty());
    let worker_runs =
        read_all_ranking_worker_runs(temp.path(), "tenant-a").expect("worker runs read");
    assert!(worker_runs.is_empty());
    let credit_events =
        read_all_credit_events(temp.path(), "tenant-a").expect("credit events read");
    assert!(credit_events.is_empty());
    let outbox = read_all_near_credit_outbox_items(temp.path(), "tenant-a").expect("outbox reads");
    assert!(outbox.is_empty());
}

