#[tokio::test]
async fn revocation_propagation_reverses_settled_credit_and_enqueues_near_reverse_receipt() {
    let Some(backend) = postgres_backend_for_ingest_test().await else {
        return;
    };
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;

    let temp = tempfile::tempdir().expect("temp dir");
    let db_mirror: Arc<dyn Database> = backend.clone();
    let mut state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        true,
        false,
        false,
    );
    Arc::make_mut(&mut state).require_db_mirror_writes = true;

    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::ModelTraining];
    envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let submission_id = envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        Json(envelope),
    )
    .await
    .expect("submission mirrors to DB");

    let Json(event) = append_credit_event_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        AxumPath(submission_id),
        Json(TraceCreditLedgerAppendRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 1.25,
            reason: Some("frontier training utility to reverse".to_string()),
            external_ref: Some("frontier:revocation-near-reversal".to_string()),
        }),
    )
    .await
    .expect("credit event mirrors to DB");

    let Json(finalized) = credit_settlement_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceCreditSettlementRunRequest {
            dry_run: false,
            policy_version: "trace-credit-policy-v1".to_string(),
            reason: "settlement before revocation".to_string(),
            issuer_approval_evidence_hash: None,
            near_contract_id: Some("trace-credits.testnet".to_string()),
            ranking_model_version: None,
            ranking_target_use: None,
        }),
    )
    .await
    .expect("settlement mirrors to DB");
    assert_eq!(finalized.near_outbox_item_count, 1);

    let revoke_status = revoke_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        AxumPath(submission_id),
    )
    .await
    .expect("contributor can revoke settled trace");
    assert_eq!(revoke_status, StatusCode::NO_CONTENT);

    let propagation_items = backend
        .list_trace_revocation_propagation_items("tenant-a", submission_id)
        .await
        .expect("revocation propagation items read");
    let reversal_items = propagation_items
        .iter()
        .filter(|item| {
            item.action == StorageTraceRevocationPropagationAction::ReverseCreditSettlement
        })
        .collect::<Vec<_>>();
    assert_eq!(reversal_items.len(), 1);
    assert_eq!(reversal_items[0].source_submission_id, submission_id);
    assert_eq!(
        reversal_items[0].target,
        StorageTraceRevocationPropagationTarget::CreditSettlement {
            credit_event_id: event.event_id,
            credit_account_ref: principal_storage_ref("token-a"),
            settlement_state_at_selection: StorageTraceCreditSettlementState::Final,
        }
    );

    let Json(response) = revocation_propagation_worker_handler(
        State(state.clone()),
        auth_headers("revocation-worker-token-a"),
        Json(TraceRevocationPropagationWorkerRequest {
            purpose: Some("reverse_settled_credit_for_revocation".to_string()),
            dry_run: false,
            limit: 10,
        }),
    )
    .await
    .expect("revocation worker reverses settled credit");
    assert_eq!(response.completed, 1);
    assert_eq!(response.failed, 0);

    let db_credit_events = backend
        .list_trace_credit_events("tenant-a")
        .await
        .expect("DB credit events read");
    let reversal_event = db_credit_events
        .iter()
        .find(|record| {
            record.external_ref.as_deref()
                == Some(&format!("revocation_credit_reversal:{}", event.event_id))
        })
        .expect("reversal credit event is mirrored");
    assert_eq!(reversal_event.submission_id, submission_id);
    assert_eq!(
        reversal_event.settlement_state,
        StorageTraceCreditSettlementState::Reversed
    );
    assert_eq!(reversal_event.points_delta, "-1.2500");

    let db_outbox = backend
        .list_trace_near_credit_outbox_items("tenant-a")
        .await
        .expect("DB NEAR outbox reads")
        .into_iter()
        .map(near_credit_outbox_item_from_storage)
        .collect::<anyhow::Result<Vec<_>>>()
        .expect("DB NEAR outbox records convert");
    assert!(
        db_outbox
            .iter()
            .any(|item| item.near_call.method_name == "settle_credit_receipt")
    );
    let reverse_items = db_outbox
        .iter()
        .filter(|item| item.near_call.method_name == "reverse_credit_receipt")
        .collect::<Vec<_>>();
    assert_eq!(reverse_items.len(), 1);
    assert_eq!(
        reverse_items[0].settlement_batch_id,
        finalized.settlement_batch_id
    );
    assert_eq!(
        reverse_items[0].status,
        StorageTraceCreditSettlementNearStatus::Pending
    );
    assert_eq!(
        reverse_items[0].near_call.args["amount_micros"],
        serde_json::json!(1_250_000)
    );

    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
}

#[tokio::test]
async fn revocation_propagation_reverses_settled_benchmark_conversion_credit_and_near_receipt() {
    let Some(backend) = postgres_backend_for_ingest_test().await else {
        return;
    };
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;

    let temp = tempfile::tempdir().expect("temp dir");
    let db_mirror: Arc<dyn Database> = backend.clone();
    let mut state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        true,
        false,
        false,
    );
    Arc::make_mut(&mut state).require_db_mirror_writes = true;

    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::BenchmarkOnly];
    envelope.trace_card.consent_scope = ConsentScope::BenchmarkOnly;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::BenchmarkGeneration];
    let submission_id = envelope.submission_id;
    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        Json(envelope),
    )
    .await
    .expect("benchmark source submission mirrors to DB");

    let Json(benchmark) = benchmark_convert_handler(
        State(state.clone()),
        auth_headers("review-token-a"),
        Json(BenchmarkConversionRequest {
            limit: Some(10),
            purpose: Some("benchmark_credit_revocation_settlement".to_string()),
            consent_scope: None,
            status: None,
            privacy_risk: None,
            external_ref: Some("benchmark:settlement-revocation".to_string()),
        }),
    )
    .await
    .expect("benchmark conversion mirrors utility credit to DB");
    assert_eq!(benchmark.item_count, 1);
    assert_eq!(benchmark.source_submission_ids, vec![submission_id]);

    let db_credit_events = backend
        .list_trace_credit_events("tenant-a")
        .await
        .expect("DB credit events read after benchmark conversion");
    let benchmark_event = db_credit_events
        .iter()
        .find(|event| {
            event.submission_id == submission_id
                && event.event_type == StorageTraceCreditEventType::BenchmarkConversion
                && event.external_ref.as_deref() == Some("benchmark:settlement-revocation")
        })
        .expect("benchmark conversion credit event is mirrored");
    let benchmark_credit_event_id = benchmark_event.credit_event_id;
    assert_eq!(benchmark_event.points_delta, "2.0000");

    let Json(finalized) = credit_settlement_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceCreditSettlementRunRequest {
            dry_run: false,
            policy_version: "trace-credit-policy-v1".to_string(),
            reason: "settle benchmark conversion credit before revocation".to_string(),
            issuer_approval_evidence_hash: None,
            near_contract_id: Some("trace-credits.testnet".to_string()),
            ranking_model_version: None,
            ranking_target_use: None,
        }),
    )
    .await
    .expect("benchmark conversion credit settles");
    assert_eq!(finalized.settled_source_event_count, 1);
    assert_eq!(finalized.settled_credit_points, 2.0);
    assert_eq!(finalized.near_outbox_item_count, 1);

    revoke_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        AxumPath(submission_id),
    )
    .await
    .expect("contributor can revoke settled benchmark source");

    let propagation_items = backend
        .list_trace_revocation_propagation_items("tenant-a", submission_id)
        .await
        .expect("revocation propagation items read");
    let reversal_items = propagation_items
        .iter()
        .filter(|item| {
            item.action == StorageTraceRevocationPropagationAction::ReverseCreditSettlement
        })
        .collect::<Vec<_>>();
    assert_eq!(reversal_items.len(), 1);
    assert_eq!(
        reversal_items[0].target,
        StorageTraceRevocationPropagationTarget::CreditSettlement {
            credit_event_id: benchmark_credit_event_id,
            credit_account_ref: principal_storage_ref("token-a"),
            settlement_state_at_selection: StorageTraceCreditSettlementState::Final,
        }
    );

    let Json(response) = revocation_propagation_worker_handler(
        State(state.clone()),
        auth_headers("revocation-worker-token-a"),
        Json(TraceRevocationPropagationWorkerRequest {
            purpose: Some("reverse_benchmark_credit_for_revocation".to_string()),
            dry_run: false,
            limit: 10,
        }),
    )
    .await
    .expect("revocation worker reverses settled benchmark credit");
    assert_eq!(response.completed, 1);
    assert_eq!(response.failed, 0);

    let db_credit_events = backend
        .list_trace_credit_events("tenant-a")
        .await
        .expect("DB credit events read after benchmark credit reversal");
    let reversal_event = db_credit_events
        .iter()
        .find(|record| {
            record.external_ref.as_deref()
                == Some(&format!(
                    "revocation_credit_reversal:{benchmark_credit_event_id}"
                ))
        })
        .expect("benchmark conversion reversal credit event is mirrored");
    assert_eq!(reversal_event.submission_id, submission_id);
    assert_eq!(
        reversal_event.event_type,
        StorageTraceCreditEventType::BenchmarkConversion
    );
    assert_eq!(
        reversal_event.settlement_state,
        StorageTraceCreditSettlementState::Reversed
    );
    assert_eq!(reversal_event.points_delta, "-2.0000");

    let db_outbox = backend
        .list_trace_near_credit_outbox_items("tenant-a")
        .await
        .expect("DB NEAR outbox reads")
        .into_iter()
        .map(near_credit_outbox_item_from_storage)
        .collect::<anyhow::Result<Vec<_>>>()
        .expect("DB NEAR outbox records convert");
    let reverse_items = db_outbox
        .iter()
        .filter(|item| item.near_call.method_name == "reverse_credit_receipt")
        .collect::<Vec<_>>();
    assert_eq!(reverse_items.len(), 1);
    assert_eq!(
        reverse_items[0].settlement_batch_id,
        finalized.settlement_batch_id
    );
    assert_eq!(
        reverse_items[0].near_call.args["amount_micros"],
        serde_json::json!(2_000_000)
    );
    assert_eq!(
        reverse_items[0].near_call.args["source_list_hash"],
        serde_json::json!(source_credit_event_ids_hash(
            "trace-credit-policy-v1",
            &[benchmark_credit_event_id],
        ))
    );

    let Json(credit) = credit_handler(State(state), auth_headers("token-a"))
        .await
        .expect("credit summary reflects benchmark reversal");
    assert_eq!(credit.credit_points_settled, 0.0);
    assert_eq!(credit.credit_points_reversed, 2.0);
    assert_eq!(credit.credit_points_total, 0.0);

    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
}

#[tokio::test]
async fn revocation_propagation_reverses_settled_ranking_utility_credit_and_near_receipt() {
    let Some(backend) = postgres_backend_for_ingest_test().await else {
        return;
    };
    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;

    let temp = tempfile::tempdir().expect("temp dir");
    let db_mirror: Arc<dyn Database> = backend.clone();
    let mut state = test_state_with_options(
        temp.path().to_path_buf(),
        Some(db_mirror),
        None,
        false,
        true,
        false,
        false,
    );
    Arc::make_mut(&mut state).require_db_mirror_writes = true;

    let (candidate, prediction) =
        seed_credit_cycle_ready_candidate(state.clone(), "trace-ranker-revocation-credit-v1").await;
    let Json(calibration) = ranking_calibration_run_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceRankingCalibrationRunRequest {
            model_version: candidate.model_version.clone(),
            target_use: TraceAllowedUse::RankingModelTraining,
            policy_version: candidate.policy_version.clone(),
            evaluation_dataset_hash: candidate.calibration_dataset_hash.clone(),
            min_label_count: Some(1),
            confidence_threshold: Some(0.5),
            max_average_absolute_error_micros: Some(100_000),
        }),
    )
    .await
    .expect("utility worker can persist revocation-test calibration");
    assert!(calibration.promotable);
    let Json(active_model) = ranking_model_promotion_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceRankingModelPromotionRequest {
            dry_run: false,
            model_version: candidate.model_version.clone(),
            target_use: TraceAllowedUse::RankingModelTraining,
            policy_version: candidate.policy_version.clone(),
            reason: "promote ranking model before revocation credit settlement".to_string(),
        }),
    )
    .await
    .expect("admin can promote revocation-test ranking model");
    assert_eq!(
        active_model.model_status,
        StorageTraceRankingModelStatus::Active
    );

    let Json(credit) = ranking_prediction_credit_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceRankingPredictionCreditRequest {
            ranking_prediction_id: prediction.ranking_prediction_id,
            reason: "prediction selected for settlement reversal coverage".to_string(),
        }),
    )
    .await
    .expect("utility worker can append prediction-bound ranking credit");
    assert_eq!(credit.appended_count, 1);
    assert_eq!(credit.skipped_existing_count, 0);
    assert_eq!(credit.credit_points_delta, 1.25);
    assert_eq!(credit.submission_id, prediction.submission_id);

    let db_credit_events = backend
        .list_trace_credit_events("tenant-a")
        .await
        .expect("DB credit events read after ranking credit");
    let ranking_event = db_credit_events
        .iter()
        .find(|event| {
            event.submission_id == prediction.submission_id
                && event.event_type == StorageTraceCreditEventType::RankingUtility
                && event.external_ref.as_deref() == Some(credit.external_ref.as_str())
        })
        .expect("ranking utility credit event is mirrored");
    let ranking_credit_event_id = ranking_event.credit_event_id;
    assert_eq!(ranking_event.points_delta, "1.2500");

    let Json(finalized) = credit_settlement_handler(
        State(state.clone()),
        auth_headers("admin-token-a"),
        Json(TraceCreditSettlementRunRequest {
            dry_run: false,
            policy_version: "trace-credit-policy-v1".to_string(),
            reason: "settle ranking utility credit before revocation".to_string(),
            issuer_approval_evidence_hash: None,
            near_contract_id: Some("trace-credits.testnet".to_string()),
            ranking_model_version: Some(active_model.model_version.clone()),
            ranking_target_use: Some(TraceAllowedUse::RankingModelTraining),
        }),
    )
    .await
    .expect("ranking utility credit settles with calibrated active model");
    assert_eq!(finalized.settled_source_event_count, 1);
    assert_eq!(finalized.settled_credit_points, 1.25);
    assert_eq!(finalized.near_outbox_item_count, 1);

    revoke_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        AxumPath(prediction.submission_id),
    )
    .await
    .expect("contributor can revoke settled ranking source");

    let propagation_items = backend
        .list_trace_revocation_propagation_items("tenant-a", prediction.submission_id)
        .await
        .expect("revocation propagation items read");
    let reversal_items = propagation_items
        .iter()
        .filter(|item| {
            item.action == StorageTraceRevocationPropagationAction::ReverseCreditSettlement
        })
        .collect::<Vec<_>>();
    assert_eq!(reversal_items.len(), 1);
    assert_eq!(
        reversal_items[0].target,
        StorageTraceRevocationPropagationTarget::CreditSettlement {
            credit_event_id: ranking_credit_event_id,
            credit_account_ref: principal_storage_ref("token-a"),
            settlement_state_at_selection: StorageTraceCreditSettlementState::Final,
        }
    );

    let Json(response) = revocation_propagation_worker_handler(
        State(state.clone()),
        auth_headers("revocation-worker-token-a"),
        Json(TraceRevocationPropagationWorkerRequest {
            purpose: Some("reverse_ranking_credit_for_revocation".to_string()),
            dry_run: false,
            limit: 10,
        }),
    )
    .await
    .expect("revocation worker reverses settled ranking credit");
    assert_eq!(response.completed, 1);
    assert_eq!(response.failed, 0);

    let db_credit_events = backend
        .list_trace_credit_events("tenant-a")
        .await
        .expect("DB credit events read after ranking credit reversal");
    let reversal_event = db_credit_events
        .iter()
        .find(|record| {
            record.external_ref.as_deref()
                == Some(&format!(
                    "revocation_credit_reversal:{ranking_credit_event_id}"
                ))
        })
        .expect("ranking utility reversal credit event is mirrored");
    assert_eq!(reversal_event.submission_id, prediction.submission_id);
    assert_eq!(
        reversal_event.event_type,
        StorageTraceCreditEventType::RankingUtility
    );
    assert_eq!(
        reversal_event.settlement_state,
        StorageTraceCreditSettlementState::Reversed
    );
    assert_eq!(reversal_event.points_delta, "-1.2500");

    let db_outbox = backend
        .list_trace_near_credit_outbox_items("tenant-a")
        .await
        .expect("DB NEAR outbox reads")
        .into_iter()
        .map(near_credit_outbox_item_from_storage)
        .collect::<anyhow::Result<Vec<_>>>()
        .expect("DB NEAR outbox records convert");
    let reverse_items = db_outbox
        .iter()
        .filter(|item| item.near_call.method_name == "reverse_credit_receipt")
        .collect::<Vec<_>>();
    assert_eq!(reverse_items.len(), 1);
    assert_eq!(
        reverse_items[0].settlement_batch_id,
        finalized.settlement_batch_id
    );
    assert_eq!(
        reverse_items[0].near_call.args["amount_micros"],
        serde_json::json!(1_250_000)
    );
    assert_eq!(
        reverse_items[0].near_call.args["source_list_hash"],
        serde_json::json!(source_credit_event_ids_hash(
            "trace-credit-policy-v1",
            &[ranking_credit_event_id],
        ))
    );

    let Json(credit_summary) = credit_handler(State(state), auth_headers("token-a"))
        .await
        .expect("credit summary reflects ranking reversal");
    assert_eq!(credit_summary.credit_points_settled, 0.0);
    assert_eq!(credit_summary.credit_points_reversed, 1.25);
    assert_eq!(credit_summary.credit_points_total, 0.0);

    cleanup_pg_trace_tenant(backend.as_ref(), "tenant-a").await;
}

#[tokio::test]
async fn utility_attestation_records_hash_only_evidence_and_appends_credit_once() {
    let temp = tempfile::tempdir().expect("temp dir");
    let state = test_state(temp.path().to_path_buf());
    let mut envelope = sample_envelope().await;
    make_metadata_only_low_risk(&mut envelope);
    envelope.consent.scopes = vec![ConsentScope::ModelTraining];
    envelope.trace_card.consent_scope = ConsentScope::ModelTraining;
    envelope.trace_card.allowed_uses = vec![TraceAllowedUse::ModelTraining];
    let submission_id = envelope.submission_id;

    let _ = submit_trace_handler(
        State(state.clone()),
        auth_headers("token-a"),
        Json(envelope),
    )
    .await
    .expect("submission succeeds");

    let malformed_attestation_error = utility_attestation_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceUtilityAttestationRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 2.0,
            use_category: "frontier_lab_training".to_string(),
            policy_version: "trace-credit-policy-v1".to_string(),
            evidence_hash: "sha256:not-canonical".to_string(),
            reason: "malformed utility attestation must not record".to_string(),
            external_ref: "frontier-lab:malformed-utility-attestation".to_string(),
            source_submission_ids: vec![submission_id],
        }),
    )
    .await
    .expect_err("malformed utility attestation is rejected");
    assert_eq!(malformed_attestation_error.0, StatusCode::BAD_REQUEST);
    assert!(
        malformed_attestation_error
            .1
            .0
            .error
            .contains("canonical sha256")
    );
    assert!(
        read_all_utility_attestations(temp.path(), "tenant-a")
            .expect("tenant-a attestations read")
            .is_empty()
    );
    assert!(
        read_all_credit_events(temp.path(), "tenant-a")
            .expect("tenant-a credit reads")
            .is_empty()
    );

    let unsafe_use_category_error = utility_attestation_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceUtilityAttestationRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 2.0,
            use_category: "frontier lab training;raw=do-not-store".to_string(),
            policy_version: "trace-credit-policy-v1".to_string(),
            evidence_hash:
                "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
                    .to_string(),
            reason: "unsafe utility attestation category must not record".to_string(),
            external_ref: "frontier-lab:unsafe-utility-attestation-category".to_string(),
            source_submission_ids: vec![submission_id],
        }),
    )
    .await
    .expect_err("unsafe utility attestation use_category is rejected");
    assert_eq!(unsafe_use_category_error.0, StatusCode::BAD_REQUEST);
    assert!(unsafe_use_category_error.1.0.error.contains("use_category"));
    assert!(
        read_all_utility_attestations(temp.path(), "tenant-a")
            .expect("tenant-a attestations read after unsafe use category")
            .is_empty()
    );
    assert!(
        read_all_credit_events(temp.path(), "tenant-a")
            .expect("tenant-a credit reads after unsafe use category")
            .is_empty()
    );

    let unsafe_policy_error = utility_attestation_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceUtilityAttestationRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 2.0,
            use_category: "frontier_lab_training".to_string(),
            policy_version: "trace-credit-policy-v1;raw=do-not-store".to_string(),
            evidence_hash:
                "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
                    .to_string(),
            reason: "unsafe utility attestation policy must not record".to_string(),
            external_ref: "frontier-lab:unsafe-utility-attestation-policy".to_string(),
            source_submission_ids: vec![submission_id],
        }),
    )
    .await
    .expect_err("unsafe utility attestation policy_version is rejected");
    assert_eq!(unsafe_policy_error.0, StatusCode::BAD_REQUEST);
    assert!(unsafe_policy_error.1.0.error.contains("policy_version"));
    assert!(
        read_all_utility_attestations(temp.path(), "tenant-a")
            .expect("tenant-a attestations read after unsafe policy")
            .is_empty()
    );
    assert!(
        read_all_credit_events(temp.path(), "tenant-a")
            .expect("tenant-a credit reads after unsafe policy")
            .is_empty()
    );

    let tenant_b_attestation_error = utility_attestation_handler(
        State(state.clone()),
        auth_headers("admin-token-b"),
        Json(TraceUtilityAttestationRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 2.0,
            use_category: "frontier_lab_training".to_string(),
            policy_version: "trace-credit-policy-v1".to_string(),
            evidence_hash:
                "sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"
                    .to_string(),
            reason: "tenant-b cannot attest tenant-a source".to_string(),
            external_ref: "frontier-lab:tenant-b-cross-tenant-attestation".to_string(),
            source_submission_ids: vec![submission_id],
        }),
    )
    .await
    .expect_err("tenant-b admin cannot attest tenant-a source");
    assert_eq!(tenant_b_attestation_error.0, StatusCode::NOT_FOUND);
    assert!(
        read_all_utility_attestations(temp.path(), "tenant-b")
            .expect("tenant-b attestations read")
            .is_empty()
    );
    assert!(
        read_all_credit_events(temp.path(), "tenant-b")
            .expect("tenant-b credit reads")
            .is_empty()
    );

    let Json(attestation) = utility_attestation_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceUtilityAttestationRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 2.0,
            use_category: "frontier_lab_training".to_string(),
            policy_version: "trace-credit-policy-v1".to_string(),
            evidence_hash:
                "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
                    .to_string(),
            reason: "frontier lab accepted batch".to_string(),
            external_ref: "frontier-lab:batch-9000".to_string(),
            source_submission_ids: vec![submission_id],
        }),
    )
    .await
    .expect("utility worker can attest training utility");
    assert_eq!(attestation.appended_count, 1);
    assert_eq!(attestation.skipped_existing_count, 0);

    let Json(retry) = utility_attestation_handler(
        State(state.clone()),
        auth_headers("utility-worker-token-a"),
        Json(TraceUtilityAttestationRequest {
            event_type: TraceCreditLedgerEventType::TrainingUtility,
            credit_points_delta: 2.0,
            use_category: "frontier_lab_training".to_string(),
            policy_version: "trace-credit-policy-v1".to_string(),
            evidence_hash:
                "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
                    .to_string(),
            reason: "frontier lab accepted batch retry".to_string(),
            external_ref: "frontier-lab:batch-9000".to_string(),
            source_submission_ids: vec![submission_id],
        }),
    )
    .await
    .expect("utility attestation retry is idempotent");
    assert_eq!(retry.attestation_id, attestation.attestation_id);
    assert_eq!(retry.appended_count, 0);
    assert_eq!(retry.skipped_existing_count, 1);

    let attestations =
        read_all_utility_attestations(temp.path(), "tenant-a").expect("attestation reads");
    assert_eq!(attestations.len(), 1);
    assert_eq!(attestations[0].source_submission_ids, vec![submission_id]);
    assert_eq!(
        attestations[0].external_ref_hash.len(),
        "sha256:".len() + 64
    );
    let serialized = serde_json::to_string(&attestations[0]).expect("attestation serializes");
    assert!(!serialized.contains("frontier lab accepted batch"));
    assert!(!serialized.contains("frontier-lab:batch-9000"));

    let credit_events = read_all_credit_events(temp.path(), "tenant-a").expect("credit reads");
    assert_eq!(credit_events.len(), 1);
    assert_eq!(
        credit_events[0].event_type,
        TraceCreditLedgerEventType::TrainingUtility
    );
    assert_eq!(credit_events[0].credit_points_delta, 2.0);
}

